const state={session:null,agents:[],agent:null,schema:[],section:'overview',socket:null,live:true,renderTimer:null,livePatchPending:false};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=(v='')=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v?new Date(v).toLocaleString('de-DE'):'–',detail=v=>{try{return JSON.parse(v)}catch{return v}};
const bool=v=>['1','true','up','enabled','active','online','operational'].includes(String(v??'').toLowerCase());
function toast(message,bad=false){const box=$('#toast');box.textContent=message;box.className=bad?'show bad':'show';setTimeout(()=>box.className='',3600)}
async function api(url,options={}){const multipart=options.body instanceof FormData,response=await fetch(url,{credentials:'same-origin',...options,headers:{...(multipart?{}:{'Content-Type':'application/json'}),...(options.headers||{})}});if(response.status===401){showLogin();throw Error('Sitzung abgelaufen')}const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.detail||`HTTP ${response.status}`);return data}
function showLogin(){$('#app').classList.add('hidden');$('#login').classList.remove('hidden')}
function roleName(role){return role==='admin'?'Administrator':role==='operator'?'Operator':'Nur-Lesen'}
async function loadBranding(){try{const brand=await api('/api/branding');$$('[data-company-logo]').forEach(image=>image.src=`${brand.logo_url}?t=${Date.now()}`)}catch{}}
function showApp(){$('#login').classList.add('hidden');$('#app').classList.remove('hidden');$('#account-name').textContent=state.session.display_name||state.session.username;$('#account-role').textContent=roleName(state.session.role);$('#version').textContent=`Version ${state.session.version}`;$$('[data-admin]').forEach(x=>x.classList.toggle('hidden',state.session.role!=='admin'));loadBranding();connectLive();navigate('dashboard')}
function heading(title,subtitle){$('#title').textContent=title;$('#subtitle').textContent=subtitle}
function active(view){$$('#main-nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view))}
function status(text,kind=''){return`<span class="badge ${kind}">${esc(text)}</span>`}
function mqttBadge(connected){const badge=$('#mqtt-status');badge.textContent=connected?'MQTT verbunden':'MQTT getrennt';badge.className=`badge ${connected?'good':'bad'}`}
function liveBadge(connected){const badge=$('#live-status');badge.textContent=connected?'Live':'Getrennt';badge.className=`live-pill ${connected?'good':'bad'}`}
function events(rows){return rows?.length?rows.map(event=>`<article class="timeline-event"><span class="event-dot"></span><div><div class="event-title"><strong>${esc(event.kind)}</strong><time>${fmt(event.created_at)}</time></div>${event.endpoint_id?`<small class="mono muted">${esc(event.endpoint_id)}</small>`:''}<details><summary>Technische Details</summary><pre class="raw">${esc(JSON.stringify(detail(event.detail),null,2))}</pre></details></div></article>`).join(''):'<div class="empty">Noch keine Ereignisse empfangen.</div>'}

function connectLive(){if(state.socket&&state.socket.readyState<2)return;const protocol=location.protocol==='https:'?'wss':'ws';const socket=new WebSocket(`${protocol}://${location.host}/api/live`);state.socket=socket;socket.onopen=()=>liveBadge(true);socket.onclose=()=>{liveBadge(false);if(!$('#login').classList.contains('hidden'))return;setTimeout(connectLive,1800)};socket.onmessage=async event=>{const update=JSON.parse(event.data);if(update.type==='hello'){mqttBadge(update.payload.mqtt);return}if(update.type==='agent'){const row=state.agents.find(x=>x.endpoint_id===update.endpoint_id);if(row){Object.assign(row,update.payload);scheduleAgentListRender()}}if(state.agent&&update.endpoint_id===state.agent.agent.endpoint_id){if(update.type==='parameter')mergeParameter(update.payload);if(update.type==='parameters')(update.payload.values||[]).forEach(mergeParameter);if(update.type==='schema')state.schema=(await api(`/api/agents/${encodeURIComponent(update.endpoint_id)}/schema`)).items;if(update.type==='agent')Object.assign(state.agent.agent,update.payload);updateShellLive();scheduleLiveRender()}}}
function mergeParameter(item){const existing=state.agent.parameters.find(x=>x.path===item.path);if(existing)Object.assign(existing,item);else state.agent.parameters.push(item);patchParameterDom(existing||item)}
function patchParameterDom(item){$$('[data-param-path]').filter(row=>row.dataset.paramPath===item.path).forEach(row=>{const value=row.querySelector('.value-cell'),updated=row.querySelector('[data-updated]');if(value)value.innerHTML=universalValue(item);if(updated)updated.textContent=fmt(item.updated_at)})}
function scheduleAgentListRender(){if(!$('#agent-table')||state.agentListTimer)return;state.agentListTimer=setTimeout(()=>{state.agentListTimer=null;if($('#agent-table'))agentTable()},250)}
function scheduleLiveRender(){clearTimeout(state.renderTimer);if(['internet','parameters','jobs','events','actions'].includes(state.section))return;state.renderTimer=setTimeout(()=>{if(state.agent&&$('#agent-panel'))renderAgentSection()},120)}

function pieChart(title,values,colors){const entries=Object.entries(values).filter(([,value])=>Number(value)>0),total=entries.reduce((sum,[,value])=>sum+Number(value),0);let offset=0;const stops=entries.map(([label,value],index)=>{const start=offset;offset+=Number(value)/Math.max(1,total)*360;return`${colors[index%colors.length]} ${start}deg ${offset}deg`});return`<section class="card overview-chart"><div class="card-head"><h2>${esc(title)}</h2><span class="muted">${total} gesamt</span></div><div class="pie-layout"><div class="pie" style="background:${total?`conic-gradient(${stops.join(',')})`:'#e3eaeb'}"><strong>${total}</strong></div><div class="pie-legend">${entries.map(([label,value],index)=>`<div><i style="background:${colors[index%colors.length]}"></i><span>${esc(label)}</span><strong>${value}</strong></div>`).join('')||'<span class="muted">Keine Daten</span>'}</div></div></section>`}
async function dashboard(){heading('Übersicht','TR-369-Betrieb und verwaltete Anschlüsse auf einen Blick');active('dashboard');const [data,genie]=await Promise.all([api('/api/dashboard'),api('/api/genieacs/status')]),jobs=data.jobs||{};mqttBadge(data.mqtt);$('#content').innerHTML=`<div class="card acs-status ${genie.ok?'connected':'disconnected'}" role="status"><span class="acs-status-dot"></span><div><small>GenieACS-Verbindung</small><strong>${esc(genie.status)}</strong><span>${genie.ok?`${genie.devices} Geräte · ${genie.latency_ms} ms`:esc(genie.error||'Nicht erreichbar')}</span></div></div><div class="stats"><button class="stat clickable good" data-open-agents><small>USP-Agenten gesamt</small><strong>${data.agents.total||0}</strong><span>Anzeigen →</span></button><button class="stat clickable ${data.agents.online===data.agents.total?'good':'warn'}" data-open-agents><small>Kürzlich online</small><strong>${data.agents.online||0}</strong><span>Anzeigen →</span></button><button class="stat clickable ${data.attention?'warn':'good'}" data-open-agents><small>Aufmerksamkeit</small><strong>${data.attention||0}</strong><span>Anzeigen →</span></button><button class="stat clickable ${data.active_errors?'bad':'good'}" data-view-errors><small>Aktive Fehler</small><strong>${data.active_errors||0}</strong><span>Anzeigen →</span></button></div><div class="overview-charts">${pieChart('Zugangsmedien',data.access,['#168794','#7d54a6','#e0a126','#3b8fce','#7d9094'])}${pieChart('Health',data.health,['#2da66f','#e0a126','#d74653','#8b9a9d'])}</div><section class="card controller-status-grid"><div><small>USP-Controller</small><strong>${data.mqtt?'Betriebsbereit':'Gestört'}</strong><span>${esc(data.endpoint_id)}</span></div><div><small>MQTT</small><strong>${data.mqtt?'Verbunden':'Getrennt'}</strong><span>Live-Kommunikation</span></div><div><small>Offene Aufträge</small><strong>${(jobs.queued||0)+(jobs.sent||0)}</strong><span>queued oder sent</span></div></section>`;$$('[data-open-agents]').forEach(button=>button.onclick=agents);const errors=$('[data-view-errors]');if(errors)errors.onclick=agents}

function trafficShell(id,title,subtitle){return`<section class="card traffic-card" data-live-preserve><div class="card-head"><div><h2>${esc(title)}</h2><p class="muted">${esc(subtitle)}</p></div><label class="traffic-range">Zeitraum<select data-traffic-hours="${esc(id)}"><option value="1">1 Stunde</option><option value="6">6 Stunden</option><option value="24" selected>24 Stunden</option><option value="168">7 Tage</option></select></label></div><div id="${esc(id)}"><div class="empty">Traffic-Verlauf wird geladen …</div></div></section>`}
function niceTrafficMax(value){if(value<=0)return 1e6;const power=10**Math.floor(Math.log10(value)),scaled=value/power,step=scaled<=1?1:scaled<=2?2:scaled<=5?5:10;return step*power}
function trafficChart(points,hours){if(points.length<2)return'<div class="empty">Noch nicht genügend Messpunkte. USP Control erfasst aktive Agenten automatisch und ressourcenschonend.</div>';const width=1000,height=310,left=78,right=20,top=18,bottom=48,start=Date.now()-hours*3600000,end=Date.now(),max=niceTrafficMax(Math.max(...points.flatMap(point=>[Number(point.down_bps)||0,Number(point.up_bps)||0]))),x=time=>left+Math.max(0,Math.min(1,(time-start)/(end-start)))*(width-left-right),y=value=>top+(1-Math.max(0,Math.min(1,value/max)))*(height-top-bottom),ticks=[0,.25,.5,.75,1],expectedGap=(hours<=1?60:hours<=24?300:900)*2500,segments=points.reduce((all,point,index)=>{if(index&&new Date(point.time)-new Date(points[index-1].time)>expectedGap)all.push([]);all.at(-1).push(point);return all},[[]]),lines=key=>segments.filter(segment=>segment.length>1).map(segment=>`<polyline class="traffic-${key==='down_bps'?'down':'up'}" points="${segment.map(point=>`${x(new Date(point.time).getTime())},${y(Number(point[key])||0)}`).join(' ')}"/>`).join('');return`<div class="traffic-chart-wrap"><svg class="traffic-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Traffic-Verlauf für die letzten ${hours} Stunden">${ticks.map(t=>{const yy=top+t*(height-top-bottom),value=max*(1-t),xx=left+t*(width-left-right);return`<g><line class="grid" x1="${left}" y1="${yy}" x2="${width-right}" y2="${yy}"/><text x="${left-10}" y="${yy+4}" text-anchor="end">${esc(bitrate(value,'bit'))}</text><text x="${xx}" y="${height-15}" text-anchor="middle">${new Date(start+t*(end-start)).toLocaleString('de-DE',{day:hours>24?'2-digit':undefined,month:hours>24?'2-digit':undefined,hour:'2-digit',minute:'2-digit'})}</text></g>`}).join('')}<line class="axis" x1="${left}" y1="${top}" x2="${left}" y2="${height-bottom}"/><line class="axis" x1="${left}" y1="${height-bottom}" x2="${width-right}" y2="${height-bottom}"/>${lines('down_bps')}${lines('up_bps')}</svg></div><div class="traffic-legend"><span><i class="down"></i>Download</span><span><i class="up"></i>Upload</span><small>Datenrate aus WAN-Zählerdifferenzen · Unterbrechungen werden als Lücke dargestellt</small></div>`}
async function loadTraffic(targetId,endpoint='',hours=24){const target=document.getElementById(targetId);if(!target)return;try{const data=await api(`/api/traffic?hours=${hours}${endpoint?`&endpoint=${encodeURIComponent(endpoint)}`:''}`);if(target.isConnected)target.innerHTML=trafficChart(data.points,hours)}catch(error){if(target.isConnected)target.innerHTML=`<div class="empty">${esc(error.message)}</div>`}}
function bindTraffic(targetId,endpoint=''){const select=$(`[data-traffic-hours="${targetId}"]`);if(select)select.onchange=()=>loadTraffic(targetId,endpoint,Number(select.value));loadTraffic(targetId,endpoint,Number(select?.value||24))}
const dashboardWithoutTraffic=dashboard;
dashboard=async function(){await dashboardWithoutTraffic();const statusGrid=$('.controller-status-grid');if(!statusGrid)return;statusGrid.insertAdjacentHTML('beforebegin',trafficShell('dashboard-traffic','Gesamttraffic','Summierter WAN-Durchsatz aller USP-Agenten'));bindTraffic('dashboard-traffic')};

async function agents(){heading('USP-Agenten','Geräte suchen, öffnen und live analysieren');active('agents');state.agents=await api('/api/agents');$('#content').innerHTML=`<section class="card"><div class="section-title"><div><h2>Verwaltete Endpunkte</h2><p class="muted">${state.agents.length} registrierte USP-Agenten</p></div></div><div class="toolbar"><input id="agent-search" placeholder="Endpoint-ID, Modell oder Seriennummer durchsuchen …"></div><div id="agent-table"></div></section>`;$('#agent-search').oninput=agentTable;agentTable()}
function agentTable(){const query=($('#agent-search')?.value||'').toLowerCase(),rows=state.agents.filter(agent=>[agent.endpoint_id,agent.serial_number,agent.model,agent.access,agent.firmware,agent.protocol_version,agent.customer_number].join(' ').toLowerCase().includes(query));$('#agent-table').innerHTML=rows.length?`<div class="card agent-list-card"><div class="agent-list-head"><span>FRITZ!Box</span><span>Kundennummer</span><span>Zugang</span><span>Firmware</span><span>USP</span><span>Health</span><span>Letzter Kontakt</span></div>${rows.map(agent=>`<button class="agent-row" data-endpoint="${esc(agent.endpoint_id)}"><span class="agent-identity"><strong>${esc(agent.model||agent.product_class||'USP-Agent')}</strong><small class="mono">${esc(agent.serial_number||agent.endpoint_id)}</small></span><strong>${esc(agent.customer_number||'–')}</strong><span>${esc(agent.access||'–')}</span><span>${esc(agent.firmware||'–')}</span><span>${esc(agent.protocol_version||'–')}</span>${status(agent.health||'Unbekannt',agent.health==='Gesund'?'good':agent.health==='Kritisch'?'bad':'warn')}<span><strong>${agent.online?'Online':'Offline'}</strong><small>${fmt(agent.last_seen)}</small></span></button>`).join('')}</div>`:'<div class="empty">Keine passenden USP-Agenten.</div>';$$('[data-endpoint]').forEach(row=>row.onclick=()=>openAgent(row.dataset.endpoint))}

function paramMap(){return new Map((state.agent?.parameters||[]).map(item=>[item.path,item]))}
function pv(path,fallback='–'){return paramMap().get(path)?.value??fallback}
function pvFirst(paths,fallback='–'){for(const path of paths){const value=paramMap().get(path)?.value;if(value!==undefined&&value!==null&&String(value)!=='')return value}return fallback}
function pnum(path){const value=Number(pv(path,NaN));return Number.isFinite(value)?value:null}
function instances(prefix){const grouped={};for(const item of state.agent.parameters){if(!item.path.startsWith(prefix))continue;const rest=item.path.slice(prefix.length),match=rest.match(/^(\d+)\.(.+)$/);if(!match)continue;(grouped[match[1]]??={})[match[2]]=item.value}return Object.entries(grouped).map(([id,values])=>({id,...values}))}
function uptime(value){let seconds=Number(value)||0,days=Math.floor(seconds/86400);seconds%=86400;return`${days?days+'T ':''}${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds%3600/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}
function bytes(value){const n=Number(value);if(!Number.isFinite(n))return'–';const units=['B','KB','MB','GB','TB'];let x=n,i=0;while(x>=1024&&i<units.length-1){x/=1024;i++}return`${x.toLocaleString('de-DE',{maximumFractionDigits:2})} ${units[i]}`}
function bitrate(value,inputUnit='kbit'){let n=Number(value);if(!Number.isFinite(n)||String(value).trim()==='')return'–';const scales={bit:1,kbit:1e3,mbit:1e6,gbit:1e9};n*=scales[String(inputUnit).toLowerCase()]||1;const units=['bit/s','kbit/s','Mbit/s','Gbit/s'];let index=0;while(Math.abs(n)>=1000&&index<units.length-1){n/=1000;index++}const maximumFractionDigits=Math.abs(n)<10?2:Math.abs(n)<100?1:0;return`${n.toLocaleString('de-DE',{minimumFractionDigits:0,maximumFractionDigits})} ${units[index]}`}
function accessType(){if(pv('Device.DOCSIS.InterfaceNumberOfEntries','0')!=='0')return'Cable';if(pv('Device.DSL.LineNumberOfEntries','0')!=='0')return'DSL';if(pv('Device.Cellular.InterfaceNumberOfEntries','0')!=='0')return'Mobilfunk';if([...paramMap().keys()].some(path=>path.startsWith('Device.Optical.')))return'Fiber';return'WAN'}

async function openAgent(endpoint){state.agent=await api(`/api/agents/${encodeURIComponent(endpoint)}`);state.schema=(await api(`/api/agents/${encodeURIComponent(endpoint)}/schema`)).items;state.section='overview';const agent=state.agent.agent;heading(pv('Device.DeviceInfo.ModelName',agent.product_class||'USP-Agent'),agent.endpoint_id);active('');renderAgentShell();api(`/api/agents/${encodeURIComponent(endpoint)}/refresh-live`,{method:'POST',body:'{}'}).catch(()=>{})}
function renderAgentShell(){const agent=state.agent.agent,online=Date.now()-new Date(agent.last_seen).getTime()<600000,cpu=Math.max(0,Math.min(100,Number(pv('Device.DeviceInfo.ProcessStatus.CPUUsage',0))||0));$('#content').innerHTML=`<button class="secondary back" id="back">← USP-Agenten</button><section class="device-hero"><div><span class="eyebrow">${esc(accessType())} · ${esc(pv('Device.DeviceInfo.Manufacturer',agent.oui||'USP'))}</span><h2>${esc(pv('Device.DeviceInfo.ModelName',agent.product_class||'USP-Agent'))}</h2><p class="mono muted">${esc(agent.endpoint_id)}</p></div><div class="device-live">${status(online?'Online':'Offline',online?'good':'')}<span class="live-pill good">Live</span></div></section><div class="stats device-kpis"><div class="stat"><small>Uptime</small><strong class="compact" data-live-path="Device.DeviceInfo.UpTime">${uptime(pv('Device.DeviceInfo.UpTime',0))}</strong></div><div class="stat cpu-stat"><div class="cpu-label"><small>CPU</small><strong data-live-path="Device.DeviceInfo.ProcessStatus.CPUUsage">${cpu}%</strong></div><div class="cpu-meter ${cpuLevel(cpu)}" role="meter" aria-label="CPU-Auslastung" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${cpu}"><span style="width:${cpu}%"></span></div></div><div class="stat"><small>Letzte Nachricht</small><strong class="compact" data-live-agent="last_seen">${fmt(agent.last_seen)}</strong></div></div><div class="device-workspace"><nav class="device-menu"><button data-section="overview">Übersicht</button><button data-section="system">System</button><button data-section="access">Anschluss</button><button data-section="internet">Internet & IP</button><button data-section="wifi">WLAN</button><button data-section="network">Heimnetz</button><button data-section="management">USP & MQTT</button><span class="menu-separator">Analyse & Technik</span><button data-section="history">Messwerte</button><button data-section="parameters">Expertenansicht</button><button data-section="jobs">Aufträge</button><button data-section="events">Ereignisse</button><button data-section="actions">USP-Aktionen</button></nav><section id="agent-panel" class="device-panel"></section></div><dialog id="model-dialog" class="model-dialog"></dialog>`;$('#back').onclick=agents;$$('[data-section]').forEach(button=>button.onclick=()=>{clearTimeout(state.renderTimer);state.renderTimer=null;state.section=button.dataset.section;renderAgentSection()});renderAgentSection()}
function cpuLevel(value){return value>=85?'critical':value>=65?'warning':'normal'}
function updateShellLive(){
  if(!state.agent)return;const cpu=Math.max(0,Math.min(100,Number(pv('Device.DeviceInfo.ProcessStatus.CPUUsage',0))||0)),cpuValue=$('[data-live-path="Device.DeviceInfo.ProcessStatus.CPUUsage"]'),meter=$('.cpu-meter');
  if(cpuValue)cpuValue.textContent=`${cpu}%`;if(meter){meter.className=`cpu-meter ${cpuLevel(cpu)}`;meter.setAttribute('aria-valuenow',String(cpu));const fill=meter.querySelector('span');if(fill)fill.style.width=`${cpu}%`}
  const up=$('[data-live-path="Device.DeviceInfo.UpTime"]');if(up)up.textContent=uptime(pv('Device.DeviceInfo.UpTime',0));const seen=$('[data-live-agent="last_seen"]');if(seen)seen.textContent=fmt(state.agent.agent.last_seen)
}
function renderAgentSection(){$$('[data-section]').forEach(button=>button.classList.toggle('active',button.dataset.section===state.section));const panel=$('#agent-panel');if(!panel)return;state.functionalCatalog={};if(state.section==='overview')renderAgentOverview(panel);if(state.section==='system'){renderSystem(panel);appendFunctionalData(panel,'Weitere Systemfunktionen',['Device.DeviceInfo.','Device.Time.'])}if(state.section==='access'){renderAccess(panel);appendFunctionalData(panel,'Weitere Anschlussfunktionen',accessPrefixes())}if(state.section==='internet')renderInternet(panel);if(state.section==='wifi'){renderWifi(panel);appendFunctionalData(panel,'Weitere WLAN-Funktionen',['Device.WiFi.'])}if(state.section==='network')renderNetwork(panel);if(state.section==='telephony')renderTelephony(panel);if(state.section==='management')renderManagement(panel);if(state.section==='history')renderHistory(panel);if(state.section==='parameters')renderParameters(panel);if(state.section==='jobs')panel.innerHTML=jobs(state.agent.jobs);if(state.section==='events')panel.innerHTML=`<section class="card"><div class="card-head"><h2>USP-Ereignisse</h2><span class="live-pill good">Live</span></div><div class="timeline">${events(state.agent.events)}</div></section>`;if(state.section==='actions'){panel.innerHTML=actions();bindActions()}}

const functionalLabels={DeviceInfo:'Geräteinformationen',Time:'Zeit & Synchronisation',IP:'IP & WAN',PPP:'PPPoE / PPP',DHCPv4:'DHCP',DOCSIS:'Cable / DOCSIS',DSL:'DSL',Cellular:'Mobilfunk',Optical:'Glasfaser',WiFi:'WLAN',Ethernet:'LAN & Ethernet',Hosts:'Heimnetzgeräte',IEEE1905:'Netzwerktopologie',Services:'Gerätedienste',BulkData:'Datenexport',LocalAgent:'USP-Agent',MQTT:'MQTT'};
const valueLabels={Enable:'Aktivierung',Status:'Status',Name:'Name',Alias:'Bezeichnung',UpTime:'Laufzeit',SoftwareVersion:'Softwareversion',HardwareVersion:'Hardwareversion',Manufacturer:'Hersteller',ModelName:'Modell',SerialNumber:'Seriennummer',IPAddress:'IP-Adresse',IPv4Address:'IPv4-Adresse',IPv6Address:'IPv6-Adresse',MACAddress:'MAC-Adresse',BytesReceived:'Empfangene Daten',BytesSent:'Gesendete Daten',PacketsReceived:'Empfangene Pakete',PacketsSent:'Gesendete Pakete',ErrorsReceived:'Empfangsfehler',ErrorsSent:'Sendefehler',SignalStrength:'Signalstärke',ChannelUtilization:'Kanalauslastung',TransmitPower:'Sendeleistung',CurrentBitRate:'Aktuelle Datenrate',MaxBitRate:'Maximale Datenrate',LastChange:'Letzte Änderung',Password:'Kennwort',Username:'Benutzername',SSID:'WLAN-Name',Channel:'Kanal',Frequency:'Frequenz',Power:'Pegel',Noise:'Rauschen'};
function accessPrefixes(){const type=accessType();return type==='Cable'?['Device.DOCSIS.']:type==='DSL'?['Device.DSL.']:type==='Mobilfunk'?['Device.Cellular.']:type==='Fiber'?['Device.Optical.','Device.XPON.']:['Device.IP.Interface.']}
function isPreparedPath(path){if(state.section==='system'&&(/DeviceInfo\.(ModelName|Manufacturer|SerialNumber|HardwareVersion|SoftwareVersion|UpTime)$/.test(path)||path.includes('.MemoryStatus.')||path.includes('.ProcessStatus.Process.')))return true;if(state.section==='access'&&accessType()==='Cable'&&/Device\.DOCSIS\.(Interface|Downstream|Upstream|DownstreamChannel|UpstreamChannel)\./.test(path))return true;if(state.section==='access'&&accessType()==='DSL'&&(/TestParams\.(HLOG|SNR|QLN|LATN)/.test(path)||/\.(SNRMpbds|SNRMpbus)$/.test(path)||path.includes('.X_AVM-DE_PLCDetection.')||/(Status|CurrRate|MaxBitRate|NoiseMargin)$/.test(path)))return true;if(state.section==='access'&&accessType()==='Fiber'&&path.startsWith('Device.XPON.'))return true;if(state.section==='wifi'&&(/Device\.WiFi\.(Radio|SSID)\./.test(path)||/Device\.WiFi\.AccessPoint\.\d+\.AssociatedDevice\./.test(path)))return true;if(state.section==='network'&&(/Device\.Ethernet\.Interface\./.test(path)||/Device\.Hosts\.Host\.\d+\.(Active|HostName|X_AVM-DE_FriendlyName|PhysAddress|AssociatedDevice|Layer1Interface|WANStats\.|IPv[46]Address\.)/.test(path)||/Device\.IEEE1905\.AL\.NetworkTopology\.IEEE1905Device\.\d+\.(FriendlyName|ManufacturerModel|ManufacturerName|IEEE1905Id|Interface\..*\.(MediaType|X_AVM-DE_Name|X_AVM-DE_SSID)|.*Neighbor\..*\.(X_AVM-DE_NeighborDevice|LinkAvailability|MACThroughputCapacity|PHYRate|RSSI|X_AVM-DE_MACThroughputCapacityRX|X_AVM-DE_MACThroughputCapacityTX))/.test(path)))return true;return false}
function functionalRows(prefixes){return state.agent.parameters.filter(row=>prefixes.some(prefix=>row.path.startsWith(prefix))&&!isPreparedPath(row.path))}
function functionalArea(path){const parts=path.split('.'),root=parts[1]||'Sonstige',sub=parts.length>3?(parts[2]||'Allgemein'):'Allgemein';return{key:`${root}.${sub}`,root,sub}}
function friendlyToken(token){const clean=String(token||'').replace(/^X_AVM.DE_/,'AVM ').replaceAll('_',' ');return valueLabels[clean]||clean.replace(/([a-zäöü])([A-ZÄÖÜ])/g,'$1 $2')}
function functionalContext(path){const parts=path.split('.'),leaf=parts.pop(),root=parts.shift(),category=parts.shift();return{label:friendlyToken(leaf),context:parts.join(' › ')||functionalLabels[category]||category}}
function preparedTable(rows){return`<div class="table-scroll functional-table"><table><thead><tr><th>Funktion</th><th>Zuordnung</th><th>Darstellung</th><th>Stand</th><th></th></tr></thead><tbody>${rows.map(row=>{const info=functionalContext(row.path),schema=parameterSchema(row.path),write=schema&&/READ_WRITE|WRITE_ONLY/.test(schema.access);return`<tr data-functional-row data-param-path="${esc(row.path)}" data-search="${esc(`${info.label} ${info.context} ${row.path} ${row.value}`.toLowerCase())}"><td><strong>${esc(info.label)}</strong></td><td>${esc(info.context||'Allgemein')}</td><td class="value-cell">${universalValue(row)}</td><td data-updated>${fmt(row.updated_at)}</td><td><div class="model-row-actions"><button class="model-icon-button" data-read-path="${esc(row.path)}" title="Jetzt lesen">↻</button>${isMetricParameter(row)?`<button class="model-chart-button" data-chart-path="${esc(row.path)}" title="Verlauf anzeigen">⌁</button>`:''}${write&&state.session.role!=='viewer'?`<button class="model-icon-button edit" data-edit-path="${esc(row.path)}" title="Ändern">✎</button>`:''}</div></td></tr>`}).join('')}</tbody></table></div>`}
function functionalContent(title,prefixes){const rows=functionalRows(prefixes),groups=new Map();rows.forEach(row=>{const area=functionalArea(row.path),group=groups.get(area.key)||{...area,rows:[]};group.rows.push(row);groups.set(area.key,group)});const metrics=rows.filter(isMetricParameter).length,writable=rows.filter(row=>{const schema=parameterSchema(row.path);return schema&&/READ_WRITE|WRITE_ONLY/.test(schema.access)}).length;return`<section class="functional-browser"><div class="card-head"><div><h2>${esc(title)}</h2><p class="muted">${rows.length.toLocaleString('de-DE')} aufbereitete Werte in ${groups.size} Funktionsgruppen</p></div><span class="live-pill good">Live</span></div><div class="functional-summary"><div><strong>${rows.length.toLocaleString('de-DE')}</strong><small>verfügbare Werte</small></div><div><strong>${metrics.toLocaleString('de-DE')}</strong><small>Messwerte mit Verlauf</small></div><div><strong>${writable.toLocaleString('de-DE')}</strong><small>bedienbare Einstellungen</small></div></div><div class="toolbar functional-toolbar"><input data-functional-search placeholder="Funktion, Gerät oder Wert suchen …"></div><div class="functional-groups">${[...groups.values()].map((group,index)=>{const id=`${state.section}-${Object.keys(state.functionalCatalog).length}`;state.functionalCatalog[id]=group;return`<details class="card functional-group" data-functional-group="${id}" ${index<2?'open':''}><summary><div><strong>${esc(functionalLabels[group.root]||friendlyToken(group.root))} · ${esc(friendlyToken(group.sub))}</strong><small>${group.rows.length} Werte</small></div><span>anzeigen</span></summary><div data-functional-body>${index<2?preparedTable(group.rows):'<div class="functional-placeholder">Details werden beim Öffnen geladen.</div>'}</div></details>`}).join('')}</div></section>`}
function loadFunctionalGroup(element,query=''){const group=state.functionalCatalog[element.dataset.functionalGroup];if(!group)return;const selected=query?group.rows.filter(row=>`${friendlyToken(row.path.split('.').pop())} ${row.path} ${row.value}`.toLowerCase().includes(query)):group.rows;element.querySelector('[data-functional-body]').innerHTML=selected.length?preparedTable(selected):'<div class="empty">Keine passenden Werte in dieser Gruppe.</div>';bindModelRows()}
function bindFunctionalPage(){const groups=$$('.functional-group');groups.forEach(group=>group.ontoggle=()=>{if(group.open)loadFunctionalGroup(group,$('[data-functional-search]')?.value.toLowerCase()||'')});const search=$('[data-functional-search]');if(search)search.oninput=()=>{const query=search.value.toLowerCase();groups.forEach(element=>{const group=state.functionalCatalog[element.dataset.functionalGroup],matches=!query||group.rows.some(row=>`${friendlyToken(row.path.split('.').pop())} ${row.path} ${row.value}`.toLowerCase().includes(query));element.classList.toggle('hidden',!matches);if(query&&matches){element.open=true;loadFunctionalGroup(element,query)}else if(!query&&element.open)loadFunctionalGroup(element)})};bindModelRows()}
function renderFunctionalPage(panel,title,subtitle,prefixes){panel.innerHTML=`<div class="section-title"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><span class="live-pill good">Live</span></div>${functionalContent('Funktionen und Messwerte',prefixes)}`;bindFunctionalPage()}
function appendFunctionalData(panel,title,prefixes){if(!functionalRows(prefixes).length)return;panel.insertAdjacentHTML('beforeend',functionalContent(title,prefixes));bindFunctionalPage()}

function rowsAt(prefix){return state.agent.parameters.filter(row=>row.path.startsWith(prefix))}
function voiceInstances(suffix){const ids=new Set(rowsAt('Device.Services.VoiceService.').map(row=>row.path.match(/^Device\.Services\.VoiceService\.(\d+)\./)?.[1]).filter(Boolean));return[...ids].flatMap(service=>instances(`Device.Services.VoiceService.${service}.${suffix}`).map(item=>({...item,service})))}
function interfaceAddresses(iface){const base=`Device.IP.Interface.${iface.id}.`,addresses=state.agent.parameters.filter(row=>row.path.startsWith(base)&&/\.IPv[46]Address\.\d+\.IPAddress$/.test(row.path)).map(row=>row.value).filter(value=>value&&!['0.0.0.0','::'].includes(String(value)));return addresses}
function editControl(path,label='Ändern'){const schema=parameterSchema(path),allowed=schema&&/READ_WRITE|WRITE_ONLY/.test(schema.access)&&state.session.role!=='viewer';return allowed?`<button class="model-icon-button edit" data-edit-path="${esc(path)}" title="${esc(label)}">✎</button>`:''}
function renderInternet(panel){
  const interfaces=instances('Device.IP.Interface.'),ppp=instances('Device.PPP.Interface.'),dhcp=instances('Device.DHCPv4.Client.'),dns=instances('Device.DNS.Client.Server.'),up=interfaces.filter(item=>String(item.Status).toLowerCase()==='up').length,addressCount=interfaces.reduce((sum,item)=>sum+interfaceAddresses(item).length,0);
  panel.innerHTML=`<div class="section-title"><div><h2>Internet & IP</h2><p>Verbindungen, Adressen, Zugangssitzungen und Namensauflösung</p></div><span class="live-pill good">Live</span></div><div class="quality-grid">${metric('IP-Schnittstellen',interfaces.length)}${metric('Aktiv',up,'',up===interfaces.length?'good':'')}${metric('IP-Adressen',addressCount)}${metric('PPP-Sitzungen',ppp.length)}</div><div class="info-grid internet-interface-grid">${interfaces.map(iface=>{const addresses=interfaceAddresses(iface),base=`Device.IP.Interface.${iface.id}.`,name=iface.Name||`IP-Schnittstelle ${iface.id}`;return`<section class="card interface-card"><div class="card-head"><div><h3>${esc(name==='avm-wg'?'WireGuard-Schnittstelle':name)}</h3><p class="muted mono">${esc(name)}</p></div>${status(iface.Status||'–',String(iface.Status).toLowerCase()==='up'?'good':'')}</div><dl class="detail-list"><div><dt>IPv4 / IPv6</dt><dd>${bool(iface.IPv4Enable)?'Ein':'Aus'} / ${bool(iface.IPv6Enable)?'Ein':'Aus'}</dd></div><div><dt>Adressen</dt><dd title="${esc(addresses.join(', '))}">${esc(addresses.join(', ')||'nicht gemeldet')}</dd></div><div><dt>Down / Up</dt><dd>${bitrate(iface['X_AVM-DE_DownstreamSpeed'],'kbit')} / ${bitrate(iface['X_AVM-DE_UpstreamSpeed'],'kbit')}</dd></div><div><dt>Traffic</dt><dd>${bytes(iface['Stats.BytesReceived'])} ↓ · ${bytes(iface['Stats.BytesSent'])} ↑</dd></div><div><dt>Fehler RX / TX</dt><dd>${esc(iface['Stats.ErrorsReceived']||'0')} / ${esc(iface['Stats.ErrorsSent']||'0')}</dd></div></dl><div class="inline-card-actions">${editControl(`${base}Enable`,'Schnittstelle aktivieren oder deaktivieren')}${editControl(`${base}IPv4Enable`,'IPv4 ändern')}${editControl(`${base}IPv6Enable`,'IPv6 ändern')}</div></section>`}).join('')||'<div class="empty">Keine IP-Schnittstellen gemeldet.</div>'}</div>${ppp.length?`<section class="card"><div class="card-head"><div><h2>PPP- und PPPoE-Verbindungen</h2><p class="muted">Authentifizierung und Sitzungszustand</p></div></div><div class="table-scroll"><table><thead><tr><th>Verbindung</th><th>Status</th><th>Benutzer</th><th>IPCP</th><th>Laufzeit</th></tr></thead><tbody>${ppp.map(item=>`<tr><td><strong>${esc(item.Name||`PPP ${item.id}`)}</strong></td><td>${status(item.Status||'–',String(item.Status).toLowerCase()==='up'?'good':'')}</td><td>${esc(item.Username||'–')}</td><td>${esc(item.IPCPStatus||'–')}</td><td>${uptime(item.LastChange)}</td></tr>`).join('')}</tbody></table></div></section>`:''}<div class="info-grid">${dhcp.length?`<section class="card"><div class="card-head"><h3>DHCP-Clients</h3><span class="badge">${dhcp.length}</span></div><dl class="detail-list">${dhcp.slice(0,8).map(item=>`<div><dt>${esc(item.Alias||`Client ${item.id}`)}</dt><dd>${esc(item.DHCPStatus||item.Status||'–')}</dd></div>`).join('')}</dl></section>`:''}${dns.length?`<section class="card"><div class="card-head"><h3>DNS-Server</h3><span class="badge">${dns.length}</span></div><dl class="detail-list">${dns.map(item=>`<div><dt>${esc(item.Type||`DNS ${item.id}`)}</dt><dd class="mono">${esc(item.DNSServer||item.IPAddress||'–')}</dd></div>`).join('')}</dl></section>`:''}</div>${functionalContent('Weitere Internet- und IP-Funktionen',['Device.IP.','Device.PPP.','Device.DHCPv4.','Device.DNS.'])}`;bindFunctionalPage();bindModelRows()
}
function renderTelephony(panel){
  const clients=voiceInstances('SIP.Client.'),networks=voiceInstances('SIP.Network.'),bases=voiceInstances('DECT.Base.'),portables=voiceInstances('DECT.Portable.'),registered=clients.filter(item=>/registered|up|enabled|ok/i.test(String(item.Status))).length;
  panel.innerHTML=`<div class="section-title"><div><h2>Telefonie & DECT</h2><p>Internetrufnummern, SIP-Netze, DECT-Basis und angemeldete Mobilteile</p></div><div class="section-actions"><span class="live-pill good">Live</span><button class="secondary" id="telephony-refresh">Telefoniedaten abrufen</button></div></div><div class="quality-grid">${metric('SIP-Konten',clients.length)}${metric('Registriert',registered,'',registered===clients.length&&clients.length?'good':'')}${metric('DECT-Basen',bases.length)}${metric('DECT-Mobilteile',portables.length)}</div><section class="card"><div class="card-head"><div><h2>Rufnummern und SIP-Konten</h2><p class="muted">Registrierungsstatus und zugeordnetes SIP-Netz</p></div></div>${clients.length?`<div class="table-scroll"><table><thead><tr><th>Rufnummer / URI</th><th>Status</th><th>Benutzer</th><th>Netz</th><th></th></tr></thead><tbody>${clients.map(item=>{const base=`Device.Services.VoiceService.${item.service}.SIP.Client.${item.id}.`;return`<tr><td><strong>${esc(item.RegisterURI||`SIP-Konto ${item.id}`)}</strong></td><td>${status(item.Status||'–',/registered|up|ok/i.test(String(item.Status))?'good':'warn')}</td><td>${esc(item.AuthUserName||'–')}</td><td class="mono">${esc(item.Network||'–')}</td><td><div class="model-row-actions">${editControl(`${base}Enable`)}${editControl(`${base}RegisterURI`)}${editControl(`${base}AuthUserName`)}</div></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Noch keine SIP-Konten vom Gerät empfangen. Der Abruf oben fordert die vollständige Telefoniestruktur per USP an.</div>'}</section>${networks.length?`<div class="info-grid">${networks.map(item=>{const base=`Device.Services.VoiceService.${item.service}.SIP.Network.${item.id}.`;return`<section class="card"><div class="card-head"><h3>SIP-Netz ${esc(item.id)}</h3>${status(bool(item.Enable)?'Aktiv':'Aus',bool(item.Enable)?'good':'')}</div><dl class="detail-list"><div><dt>Registrar</dt><dd>${esc(item.RegistrarServer||'–')}:${esc(item.RegistrarServerPort||'–')}</dd></div><div><dt>Proxy</dt><dd>${esc(item.ProxyServer||'–')}:${esc(item.ProxyServerPort||'–')}</dd></div><div><dt>Outbound-Proxy</dt><dd>${esc(item.OutboundProxy||'–')}:${esc(item.OutboundProxyPort||'–')}</dd></div><div><dt>STUN</dt><dd>${bool(item.STUNEnable)?esc(item.STUNServer||'Aktiv'):'Aus'}</dd></div></dl><div class="inline-card-actions">${editControl(`${base}Enable`)}${editControl(`${base}RegistrarServer`)}${editControl(`${base}ProxyServer`)}</div></section>`}).join('')}</div>`:''}<div class="info-grid dect-grid">${bases.map(item=>{const base=`Device.Services.VoiceService.${item.service}.DECT.Base.${item.id}.`;return`<section class="card dect-base-card"><div class="card-head"><div><h3>DECT-Basis ${esc(item.id)}</h3><p class="muted">${esc(item.Standard||'DECT')}</p></div>${status(bool(item.Enable)?'Aktiv':'Aus',bool(item.Enable)?'good':'')}</div><dl class="detail-list"><div><dt>RFPI</dt><dd class="mono">${esc(item.RFPI||'–')}</dd></div><div><dt>Mobilteile max.</dt><dd>${esc(item.MaxSupportedPP||'–')}</dd></div><div><dt>Repeater</dt><dd>${bool(item.RepeaterSupportEnabled)?'Unterstützt':'Nicht gemeldet'}</dd></div></dl><div class="inline-card-actions">${editControl(`${base}Enable`,'DECT-Basis aktivieren oder deaktivieren')}</div></section>`}).join('')}${portables.map(item=>`<section class="card dect-handset-card"><div class="card-head"><div><h3>${esc(item['X_AVM-DE_Name']||`DECT-Mobilteil ${item.id}`)}</h3><p class="muted">${esc(item['X_AVM-DE_Model']||'Mobilteil')}</p></div><span class="dect-icon">⌕</span></div><dl class="detail-list"><div><dt>Hersteller</dt><dd>${esc(item['X_AVM-DE_Manufacturer']||'–')}</dd></div><div><dt>Firmware</dt><dd>${esc(item.SoftwareVersion||'–')}</dd></div><div><dt>Basis</dt><dd class="mono">${esc(item.BaseAttachedTo||'–')}</dd></div><div><dt>IPUI</dt><dd class="mono">${esc(item.IPUI||'–')}</dd></div><div><dt>Codecs</dt><dd title="${esc(item.CodecList||'')}">${esc(item.CodecList||'–')}</dd></div></dl></section>`).join('')}${!bases.length&&!portables.length?'<div class="empty">Keine DECT-Basis oder Mobilteile gemeldet.</div>':''}</div>`;bindModelRows();$('#telephony-refresh').onclick=refreshTelephony
}
async function refreshTelephony(silent=false){const button=$('#telephony-refresh');if(button){button.disabled=true;button.textContent='Abruf läuft …'}try{await api(`/api/agents/${encodeURIComponent(state.agent.agent.endpoint_id)}/jobs`,{method:'POST',body:JSON.stringify({action:'get',payload:{paths:['Device.Services.VoiceService.'],max_depth:0}})});if(!silent)toast('Telefonie-, Rufnummern- und DECT-Daten wurden angefordert')}catch(error){toast(error.message,true);if(button){button.disabled=false;button.textContent='Telefoniedaten abrufen'}}}
function renderServices(panel){
  const rows=state.agent.parameters.filter(row=>(row.path.startsWith('Device.Services.')&&!row.path.startsWith('Device.Services.VoiceService'))||row.path.startsWith('Device.BulkData.')),areas=new Map();for(const row of rows){const match=row.path.match(/^Device\.(?:Services\.)?([^.]+)/),name=match?.[1]||'Sonstige',area=areas.get(name)||{name,rows:[],enabled:0,statuses:new Set()};area.rows.push(row);if(/\.Enable$/.test(row.path)&&bool(row.value))area.enabled++;if(/\.Status$/.test(row.path)&&row.value)area.statuses.add(String(row.value));areas.set(name,area)}
  const servicePrefixes=[...areas.keys()].map(name=>name==='BulkData'?'Device.BulkData.':`Device.Services.${name}.`);panel.innerHTML=`<div class="section-title"><div><h2>Dienste</h2><p>Aktive Gerätedienste, Datenexport und zusätzliche Servicefunktionen</p></div><div class="section-actions"><span class="live-pill good">Live</span><button class="secondary" id="services-refresh">Dienste abrufen</button></div></div><div class="info-grid service-overview-grid">${[...areas.values()].map(area=>`<section class="card service-area-card"><div class="card-head"><div><h3>${esc(functionalLabels[area.name]||friendlyToken(area.name))}</h3><p class="muted">${area.rows.length} verfügbare Werte</p></div>${status(area.enabled?`${area.enabled} aktiv`:area.statuses.size?[...area.statuses][0]:'Verfügbar',area.enabled?'good':'')}</div><div class="service-meter"><span style="width:${Math.min(100,area.rows.length/Math.max(1,rows.length)*100)}%"></span></div><small>${esc([...area.statuses].slice(0,3).join(' · ')||'Konfiguration und Status')}</small></section>`).join('')||'<div class="empty">Noch keine zusätzlichen Gerätedienste empfangen. Der Abruf oben fordert die vollständige Servicestruktur per USP an.</div>'}</div>${functionalContent('Dienstekonfiguration und Messwerte',servicePrefixes)}`;bindFunctionalPage();$('#services-refresh').onclick=refreshServices
}
async function refreshServices(silent=false){const button=$('#services-refresh');if(button){button.disabled=true;button.textContent='Abruf läuft …'}try{await api(`/api/agents/${encodeURIComponent(state.agent.agent.endpoint_id)}/jobs`,{method:'POST',body:JSON.stringify({action:'get',payload:{paths:['Device.Services.','Device.BulkData.'],max_depth:0}})});if(!silent)toast('Gerätedienste und Datenexport wurden angefordert')}catch(error){toast(error.message,true);if(button){button.disabled=false;button.textContent='Dienste abrufen'}}}
function renderManagement(panel){
  const rows=state.agent.parameters.filter(row=>(row.path.startsWith('Device.Services.')&&!row.path.startsWith('Device.Services.VoiceService'))||row.path.startsWith('Device.BulkData.')),areas=new Map();for(const row of rows){const match=row.path.match(/^Device\.(?:Services\.)?([^.]+)/),name=match?.[1]||'Sonstige',area=areas.get(name)||{name,rows:[],enabled:0,statuses:new Set()};area.rows.push(row);if(/\.Enable$/.test(row.path)&&bool(row.value))area.enabled++;if(/\.Status$/.test(row.path)&&row.value)area.statuses.add(String(row.value));areas.set(name,area)}
  const servicePrefixes=[...areas.keys()].map(name=>name==='BulkData'?'Device.BulkData.':`Device.Services.${name}.`),allPrefixes=['Device.LocalAgent.','Device.MQTT.',...servicePrefixes];panel.innerHTML=`<div class="section-title"><div><h2>USP & MQTT</h2><p>Controller, Transport, Subscriptions, MQTT-Verbindungen und Gerätedienste</p></div><div class="section-actions"><span class="live-pill good">Live</span><button class="secondary" id="services-refresh">Gerätedienste abrufen</button></div></div><section class="card"><div class="card-head"><div><h2>Gerätedienste & Messdatenexport</h2><p class="muted">Zusätzliche USP-Dienste sowie BulkData-Exportfunktionen des Geräts</p></div></div><div class="info-grid service-overview-grid">${[...areas.values()].map(area=>`<article class="service-area-card"><div class="card-head"><div><h3>${esc(functionalLabels[area.name]||friendlyToken(area.name))}</h3><p class="muted">${area.rows.length} verfügbare Werte</p></div>${status(area.enabled?`${area.enabled} aktiv`:area.statuses.size?[...area.statuses][0]:'Verfügbar',area.enabled?'good':'')}</div><div class="service-meter"><span style="width:${Math.min(100,area.rows.length/Math.max(1,rows.length)*100)}%"></span></div><small>${esc([...area.statuses].slice(0,3).join(' · ')||'Konfiguration und Status')}</small></article>`).join('')||'<div class="empty">Noch keine zusätzlichen Gerätedienste empfangen. „Gerätedienste abrufen“ fordert sie per USP an.</div>'}</div></section>${functionalContent('USP-, MQTT- und Dienstefunktionen',allPrefixes)}`;bindFunctionalPage();$('#services-refresh').onclick=refreshServices
}

function metric(label,value,unit='',kind=''){if(unit==='Mbit/s'){value=bitrate(value,'mbit');unit=''}else if(unit==='kbit/s'){value=bitrate(value,'kbit');unit=''}const percent=unit==='%'&&Number.isFinite(Number(value)),numeric=percent?Math.max(0,Math.min(100,Number(value))):0;return`<div class="metric ${kind}"><span>${esc(label)}</span><strong>${esc(value)}${unit?` <small>${esc(unit)}</small>`:''}</strong>${percent?`<div class="metric-percent" role="meter" aria-label="${esc(label)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${numeric}"><span style="width:${numeric}%"></span></div>`:''}</div>`}
function renderAgentOverview(panel){const total=pnum('Device.DeviceInfo.MemoryStatus.Total'),free=pnum('Device.DeviceInfo.MemoryStatus.Free'),memory=total&&free?Math.round((total-free)/total*100):'–';panel.innerHTML=`<div class="section-title"><div><h2>Betriebsübersicht</h2><p>Live-Zustand der wichtigsten Gerätebereiche</p></div><div class="section-actions"><button class="secondary" id="live-refresh">Werte jetzt lesen</button>${state.session.role!=='viewer'?'<button class="primary" id="live-subscribe">Live-Updates aktivieren</button>':''}</div></div><div class="quality-grid">${metric('Gerätestatus',pv('Device.DeviceInfo.X_AVM-DE_UpdateState','Bereit'))}${metric('CPU',pv('Device.DeviceInfo.ProcessStatus.CPUUsage'),'%',Number(pv('Device.DeviceInfo.ProcessStatus.CPUUsage',0))>80?'bad':'good')}${metric('Arbeitsspeicher',memory,'%',memory>85?'bad':'good')}${metric('Zugang',accessType())}</div><div class="info-grid"><section class="card"><h3>Gerät</h3><dl class="detail-list"><div><dt>Modell</dt><dd>${esc(pv('Device.DeviceInfo.ModelName'))}</dd></div><div><dt>Software</dt><dd>${esc(pv('Device.DeviceInfo.SoftwareVersion',pv('Device.DeviceInfo.FirmwareImage.1.Version')))}</dd></div><div><dt>Hardware</dt><dd>${esc(pv('Device.DeviceInfo.HardwareVersion'))}</dd></div><div><dt>Seriennummer</dt><dd>${esc(pv('Device.DeviceInfo.SerialNumber',state.agent.agent.serial_number))}</dd></div></dl></section><section class="card"><h3>USP-Verbindung</h3><dl class="detail-list"><div><dt>Endpoint</dt><dd class="mono">${esc(state.agent.agent.endpoint_id)}</dd></div><div><dt>Antwort-Topic</dt><dd class="mono">${esc(state.agent.agent.reply_topic)}</dd></div><div><dt>Letzter Kontakt</dt><dd>${fmt(state.agent.agent.last_seen)}</dd></div><div><dt>Parameter</dt><dd>${state.agent.parameters.length.toLocaleString('de-DE')}</dd></div></dl></section></div>`;$('#live-refresh').onclick=refreshLive;if($('#live-subscribe'))$('#live-subscribe').onclick=subscribeLive}
const renderAgentOverviewWithoutTraffic=renderAgentOverview;
renderAgentOverview=function(panel){renderAgentOverviewWithoutTraffic(panel);const endpoint=state.agent.agent.endpoint_id;panel.insertAdjacentHTML('beforeend',trafficShell('agent-traffic','Traffic dieses USP-Agenten','WAN-Durchsatz des ausgewählten Anschlusses'));if(!panel.hidden)bindTraffic('agent-traffic',endpoint)};
function renderSystem(panel){const agent=state.agent.agent,total=pnum('Device.DeviceInfo.MemoryStatus.Total'),free=pnum('Device.DeviceInfo.MemoryStatus.Free'),used=total!=null&&free!=null?total-free:null,memory=total&&used!=null?Math.round(used/total*100):null,processes=instances('Device.DeviceInfo.ProcessStatus.Process.'),model=pvFirst(['Device.DeviceInfo.ModelName','Device.DeviceInfo.ProductClass'],agent.product_class||'FRITZ!Box'),manufacturer=pv('Device.DeviceInfo.Manufacturer',agent.oui||'AVM'),firmware=pvFirst(['Device.DeviceInfo.SoftwareVersion','Device.DeviceInfo.FirmwareImage.1.Version','Device.DeviceInfo.AdditionalSoftwareVersion']),hardware=pvFirst(['Device.DeviceInfo.HardwareVersion','Device.DeviceInfo.ProductClass']),serial=pv('Device.DeviceInfo.SerialNumber',agent.serial_number||'–');panel.innerHTML=`<div class="section-title"><div><h2>System & Gerät</h2><p>Gerätezustand, Ressourcen, Firmware und laufende Dienste</p></div><div class="section-actions"><span class="live-pill good">Live</span><button class="secondary" id="system-refresh">Systemdaten aktualisieren</button></div></div><div class="quality-grid">${metric('CPU',pv('Device.DeviceInfo.ProcessStatus.CPUUsage'),'%',Number(pv('Device.DeviceInfo.ProcessStatus.CPUUsage',0))>80?'bad':'good')}${metric('Arbeitsspeicher',memory??'–','%',memory>85?'bad':'good')}${metric('Laufzeit',uptime(pv('Device.DeviceInfo.UpTime',0)))}${metric('Prozesse',processes.length)}</div><div class="info-grid"><section class="card"><div class="card-head"><h3>Gerät und Firmware</h3>${status(pv('Device.DeviceInfo.X_AVM-DE_UpdateState','Bereit'),'good')}</div><dl class="detail-list"><div><dt>Modell</dt><dd>${esc(model)}</dd></div><div><dt>Hersteller</dt><dd>${esc(manufacturer)}</dd></div><div><dt>FRITZ!OS / Firmware</dt><dd>${esc(firmware)}</dd></div><div><dt>Hardware</dt><dd>${esc(hardware)}</dd></div><div><dt>Seriennummer</dt><dd>${esc(serial)}</dd></div><div><dt>Produktklasse</dt><dd>${esc(agent.product_class||'–')}</dd></div></dl></section><section class="card"><h3>Speicherbelegung</h3>${memory==null?'<div class="empty">Keine Speicherdaten.</div>':`<div class="memory-donut" style="--memory:${memory}"><div><strong>${memory}%</strong><small>belegt</small></div></div><dl class="detail-list"><div><dt>Gesamt</dt><dd>${bytes(total)}</dd></div><div><dt>Belegt</dt><dd>${bytes(used)}</dd></div><div><dt>Frei</dt><dd>${bytes(free)}</dd></div></dl>`}</section></div><section class="card"><div class="card-head"><div><h2>Laufende Systemprozesse</h2><p class="muted">${processes.length} von der FRITZ!Box gemeldete Prozesse</p></div></div>${processes.length?`<div class="table-scroll process-table"><table><thead><tr><th>PID</th><th>Dienst</th><th>Status</th><th>CPU-Zeit</th><th>Speicher</th><th>Priorität</th></tr></thead><tbody>${processes.map(proc=>`<tr><td>${esc(proc.PID||proc.id)}</td><td><strong>${esc(String(proc.Command||proc.Name||'Systemprozess').split(' ')[0].split('/').pop())}</strong><small>${esc(proc.Command||'')}</small></td><td>${esc(proc.State||'–')}</td><td>${esc(proc.CPUTime||'–')}</td><td>${proc.Size?bytes(proc.Size):'–'}</td><td>${esc(proc.Priority||'–')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Noch keine Prozessliste empfangen. „Systemdaten aktualisieren“ fordert sie jetzt vollständig per USP an.</div>'}</section>`;$('#system-refresh').onclick=refreshSystem}
async function refreshSystem(){try{await api(`/api/agents/${encodeURIComponent(state.agent.agent.endpoint_id)}/jobs`,{method:'POST',body:JSON.stringify({action:'get',payload:{paths:['Device.DeviceInfo.'],max_depth:0}})});toast('Geräte-, Firmware- und Prozessdaten wurden angefordert')}catch(error){toast(error.message,true)}}
async function refreshLive(){try{await api(`/api/agents/${encodeURIComponent(state.agent.agent.endpoint_id)}/refresh-live`,{method:'POST',body:'{}'});toast('Aktuelle Werte wurden angefordert')}catch(error){toast(error.message,true)}}
async function subscribeLive(){if(!confirm('Persistente USP-ValueChange-Subscription für die konfigurierten Live-Pfade aktivieren?'))return;try{const result=await api(`/api/agents/${encodeURIComponent(state.agent.agent.endpoint_id)}/subscribe-live`,{method:'POST',body:'{}'});toast(result.status==='already_active'?'Live-Updates sind bereits aktiv':'Live-Subscription wurde an das Gerät gesendet')}catch(error){toast(error.message,true)}}

function arrayParameter(path){const value=pv(path,'');return csvValues(value)||[]}
function spectrumSvg(series,unit='dB'){const all=series.flatMap(line=>line.values.filter(Number.isFinite)),width=900,height=260,left=52,right=18,top=18,bottom=38;if(all.length<2)return'<div class="empty">Keine verwertbaren Messpunkte vorhanden.</div>';const min=Math.min(...all),max=Math.max(...all),range=Math.max(1,max-min),count=Math.max(...series.map(line=>line.values.length));const colors=['#087f8c','#d18b20','#8a58a5','#4d9c67'];return`<svg class="spectrum-chart" viewBox="0 0 ${width} ${height}"><line x1="${left}" y1="${top}" x2="${left}" y2="${height-bottom}"/><line x1="${left}" y1="${height-bottom}" x2="${width-right}" y2="${height-bottom}"/>${[0,.25,.5,.75,1].map(t=>`<g><line class="grid" x1="${left}" y1="${top+t*(height-top-bottom)}" x2="${width-right}" y2="${top+t*(height-top-bottom)}"/><text x="${left-8}" y="${top+t*(height-top-bottom)+4}" text-anchor="end">${(max-t*range).toLocaleString('de-DE',{maximumFractionDigits:1})}</text></g>`).join('')}${series.map((line,index)=>{const runs=[];let run=[];line.values.forEach((value,i)=>{if(Number.isFinite(value))run.push(`${left+i/Math.max(1,count-1)*(width-left-right)},${top+(max-value)/range*(height-top-bottom)}`);else if(run.length){runs.push(run);run=[]}});if(run.length)runs.push(run);return runs.filter(points=>points.length>1).map(points=>`<polyline style="stroke:${colors[index%colors.length]}" points="${points.join(' ')}"/>`).join('')}).join('')}<text x="${left}" y="${height-10}">Träger / Frequenzverlauf</text><text x="12" y="${top}" transform="rotate(-90 12 ${top})">${esc(unit)}</text></svg><div class="chart-legend">${series.map((line,index)=>`<span><i style="background:${colors[index%colors.length]}"></i>${esc(line.label)}</span>`).join('')}</div>`}
function filledCarrierAreas(values,color,maxCarrier=8192){const carrierStep=16,width=1000,height=280,left=48,right=18,top=18,bottom=42,x=index=>left+index*carrierStep/maxCarrier*(width-left-right),y=value=>top+(60-Math.max(0,Math.min(60,value)))/60*(height-top-bottom);const runs=[];let run=[];values.forEach((value,index)=>{if(Number.isFinite(value)&&value>0)run.push({index,value});else if(run.length){runs.push(run);run=[]}});if(run.length)runs.push(run);return runs.map(points=>{const first=points[0],last=points[points.length-1],polygon=[`${x(first.index)},${y(0)}`,...points.map(point=>`${x(point.index)},${y(point.value)}`),`${x(last.index)},${y(0)}`].join(' ');return`<polygon points="${polygon}" fill="${color}"/>`}).join('')}
function carrierLine(values,color,maxCarrier=8192){const carrierStep=16,width=1000,height=280,left=48,right=18,top=18,bottom=42,x=index=>left+index*carrierStep/maxCarrier*(width-left-right),y=value=>top+(60-Math.max(0,Math.min(60,value)))/60*(height-top-bottom);const runs=[];let run=[];values.forEach((value,index)=>{if(Number.isFinite(value)&&value>0)run.push(`${x(index)},${y(value)}`);else if(run.length){runs.push(run);run=[]}});if(run.length)runs.push(run);return runs.filter(points=>points.length>1).map(points=>`<polyline points="${points.join(' ')}" style="stroke:${color}"/>`).join('')}
function dslFritzSpectrum(){const scale=values=>values.map(value=>value>0?value/2:NaN),down=scale(arrayParameter('Device.DSL.Line.1.TestParams.SNRpsds')),up=scale(arrayParameter('Device.DSL.Line.1.TestParams.SNRpsus')),minDown=scale(arrayParameter('Device.DSL.X_AVM-DE_PLCDetection.SNRpsdsDayMin')),maxDown=scale(arrayParameter('Device.DSL.X_AVM-DE_PLCDetection.SNRpsdsDayMax')),minUp=scale(arrayParameter('Device.DSL.X_AVM-DE_PLCDetection.SNRpsusDayMin')),maxUp=scale(arrayParameter('Device.DSL.X_AVM-DE_PLCDetection.SNRpsusDayMax'));if(!down.some(Number.isFinite)&&!up.some(Number.isFinite))return'';const width=1000,height=280,left=48,right=18,top=18,bottom=42,ticks=[0,1024,2048,3072,4096,5120,6144,7168,8192];return`<section class="card fritz-spectrum-card"><div class="card-head"><div><h2>DSL-Spektrum</h2><p class="muted">Signal-/Rausch-Verhältnis je Träger · Profil ${esc(pv('Device.DSL.Line.1.CurrentProfile','–'))}</p></div><span class="live-pill good">USP-Messwerte</span></div><div class="fritz-spectrum-wrap"><svg class="fritz-spectrum" viewBox="0 0 ${width} ${height}"><rect x="${left}" y="${top}" width="${width-left-right}" height="${height-top-bottom}"/>${[0,20,40,60].map(value=>{const y=top+(60-value)/60*(height-top-bottom);return`<g><line class="grid" x1="${left}" y1="${y}" x2="${width-right}" y2="${y}"/><text x="${left-8}" y="${y+4}" text-anchor="end">${value}</text></g>`}).join('')}${filledCarrierAreas(down,'#ffe900')}${filledCarrierAreas(up,'#9b73b7')}${carrierLine(minDown,'#ff9800')}${carrierLine(minUp,'#ff9800')}${carrierLine(maxDown,'#c77918')}${carrierLine(maxUp,'#c77918')}${ticks.map(carrier=>{const x=left+carrier/8192*(width-left-right);return`<g><line x1="${x}" y1="${height-bottom}" x2="${x}" y2="${height-bottom+5}"/><text x="${x}" y="${height-20}" text-anchor="middle">${carrier}</text><text x="${x}" y="${height-7}" text-anchor="middle" class="frequency">${(carrier*4.3125).toLocaleString('de-DE',{maximumFractionDigits:0})}</text></g>`}).join('')}<text x="12" y="${top}" transform="rotate(-90 12 ${top})">dB</text></svg></div><div class="fritz-legend"><span><i class="down"></i>Empfangsrichtung (Downstream)</span><span><i class="up"></i>Senderichtung (Upstream)</span><span><i class="minimum"></i>Minimum</span><span><i class="maximum"></i>Maximum</span></div><div class="axis-caption">Träger / Frequenz in kHz</div><div class="notice compact-notice">Die Bitbelegung je Träger wird von dieser FRITZ!OS-Version im USP-Datenmodell nicht geliefert. Deshalb zeigt der Controller hier keine geschätzten oder erfundenen Bitwerte.</div></section>`}
function dslHlogSpectrum(){const down=arrayParameter('Device.DSL.Line.1.TestParams.HLOGpsds').map(value=>value<1000?value/10:NaN),up=arrayParameter('Device.DSL.Line.1.TestParams.HLOGpsus').map(value=>value<1000?value/10:NaN);if(!down.some(Number.isFinite)&&!up.some(Number.isFinite))return'';const width=1000,height=280,left=48,right=18,top=18,bottom=42,ticks=[0,1024,2048,3072,4096,5120,6144,7168,8192];return`<section class="card fritz-spectrum-card"><div class="card-head"><div><h2>HLOG – Leitungsdämpfung je Träger</h2><p class="muted">Gefüllte Darstellung der gemessenen Kanalübertragungsfunktion</p></div><span class="live-pill good">USP-Messwerte</span></div><div class="fritz-spectrum-wrap"><svg class="fritz-spectrum hlog-spectrum" viewBox="0 0 ${width} ${height}"><rect x="${left}" y="${top}" width="${width-left-right}" height="${height-top-bottom}"/>${[0,20,40,60].map(value=>{const y=top+(60-value)/60*(height-top-bottom);return`<g><line class="grid" x1="${left}" y1="${y}" x2="${width-right}" y2="${y}"/><text x="${left-8}" y="${y+4}" text-anchor="end">${value}</text></g>`}).join('')}${filledCarrierAreas(down,'#ffe900')}${filledCarrierAreas(up,'#9b73b7')}${ticks.map(carrier=>{const x=left+carrier/8192*(width-left-right);return`<g><line x1="${x}" y1="${height-bottom}" x2="${x}" y2="${height-bottom+5}"/><text x="${x}" y="${height-20}" text-anchor="middle">${carrier}</text><text x="${x}" y="${height-7}" text-anchor="middle" class="frequency">${(carrier*4.3125).toLocaleString('de-DE',{maximumFractionDigits:0})}</text></g>`}).join('')}<text x="12" y="${top}" transform="rotate(-90 12 ${top})">dB</text></svg></div><div class="fritz-legend"><span><i class="down"></i>Empfangsrichtung (Downstream)</span><span><i class="up"></i>Senderichtung (Upstream)</span></div><div class="axis-caption">Träger / Frequenz in kHz</div></section>`}
function validBands(path,invalid){return arrayParameter(path).map(value=>invalid.includes(value)?NaN:value/10)}
function dslBandAnalysis(){const snrDown=validBands('Device.DSL.Line.1.SNRMpbds',[-3276]),snrUp=validBands('Device.DSL.Line.1.SNRMpbus',[-3276]),attDown=validBands('Device.DSL.Line.1.TestParams.LATNds',[62260]),attUp=validBands('Device.DSL.Line.1.TestParams.LATNus',[62260]),bands=Math.max(snrDown.length,snrUp.length,attDown.length,attUp.length);if(!bands)return'';return`<section class="card band-analysis"><div class="card-head"><div><h2>DSL-Bandanalyse</h2><p class="muted">SNR-Marge und Leitungsdämpfung je gemeldetem Frequenzband</p></div></div><div class="band-grid">${Array.from({length:bands},(_,index)=>{const values=[['SNR ↓',snrDown[index]],['SNR ↑',snrUp[index]],['Dämpfung ↓',attDown[index]],['Dämpfung ↑',attUp[index]]].filter(([,value])=>Number.isFinite(value));if(!values.length)return'';return`<article><strong>Band ${index+1}</strong>${values.map(([label,value])=>`<div><span>${label}</span><b>${value.toLocaleString('de-DE',{maximumFractionDigits:1})} dB</b><i><em style="width:${Math.min(100,value/6*10)}%"></em></i></div>`).join('')}</article>`}).join('')}</div></section>`}
function dslPlcSummary(){const enabled=bool(pv('Device.DSL.X_AVM-DE_PLCDetection.InterferenceDetection','0')),devices=Number(pv('Device.DSL.X_AVM-DE_PLCDetection.ActivePLCDevices','0'))||0,last=pv('Device.DSL.X_AVM-DE_PLCDetection.LastInterferenceTime','');return`<section class="card plc-card"><div class="card-head"><div><h2>PLC-Störungserkennung</h2><p class="muted">Auswertung der AVM-PLC-Detection und der Tages-Min-/Max-Werte im Spektrum</p></div>${status(enabled?'Überwachung aktiv':'Überwachung aus',enabled?'good':'warn')}</div><div class="quality-grid compact">${metric('Aktive PLC-Geräte',devices,'',devices?'bad':'good')}${metric('Letzte erkannte Störung',last?fmt(last):'Keine')}</div><div class="notice compact-notice">Die orangefarbenen und braunen Linien im DSL-Spektrum zeigen Tagesminimum und Tagesmaximum. Größere Abstände zum aktuellen SNR können auf zeitabhängige Störer hinweisen.</div></section>`}
function dslSpectrumCards(){const qln=[{label:'Downstream',values:arrayParameter('Device.DSL.Line.1.TestParams.QLNpsds').map(value=>value===0?NaN:value/2-23)},{label:'Upstream',values:arrayParameter('Device.DSL.Line.1.TestParams.QLNpsus').map(value=>value===0?NaN:value/2-23)}].filter(x=>x.values.some(Number.isFinite));return`${dslHlogSpectrum()}${qln.length?`<section class="card spectrum-card"><div class="card-head"><div><h2>QLN – Leitungsrauschen je Träger</h2><p class="muted">Quiet Line Noise aus den USP-Testparametern</p></div></div>${spectrumSvg(qln,'dB')}</section>`:''}${dslBandAnalysis()}${dslPlcSummary()}`}
function cablePowerChart(rows){const points=rows.map(row=>({id:row.ID||row.id,frequency:Number(row.Frequency)/1e6,power:Number(row.Power)/10,width:Number(row.Width)/1e6,modulation:row.Modulation||'–'})).filter(x=>Number.isFinite(x.power)&&Number.isFinite(x.frequency)&&Number.isFinite(x.width));if(points.length<2)return'';const width=1000,height=280,left=56,right=18,top=18,bottom=44,minFrequency=Math.min(...points.map(x=>x.frequency-x.width/2)),maxFrequency=Math.max(...points.map(x=>x.frequency+x.width/2)),frequencyRange=Math.max(1,maxFrequency-minFrequency),minPower=Math.floor(Math.min(...points.map(x=>x.power))-2),maxPower=Math.ceil(Math.max(...points.map(x=>x.power))+2),powerRange=Math.max(1,maxPower-minPower),x=value=>left+(value-minFrequency)/frequencyRange*(width-left-right),y=value=>top+(maxPower-value)/powerRange*(height-top-bottom),ticks=Array.from({length:6},(_,index)=>minFrequency+index/5*frequencyRange);return`<section class="card fritz-spectrum-card cable-spectrum-card"><div class="card-head"><div><h2>Downstream-Pegel über Frequenz</h2><p class="muted">Empfangspegel nach tatsächlicher Mittenfrequenz und Kanalbreite</p></div><span class="live-pill good">DOCSIS-Messwerte</span></div><div class="fritz-spectrum-wrap"><svg class="fritz-spectrum cable-spectrum" viewBox="0 0 ${width} ${height}"><rect x="${left}" y="${top}" width="${width-left-right}" height="${height-top-bottom}"/>${Array.from({length:5},(_,index)=>maxPower-index/4*powerRange).map(value=>`<g><line class="grid" x1="${left}" y1="${y(value)}" x2="${width-right}" y2="${y(value)}"/><text x="${left-8}" y="${y(value)+4}" text-anchor="end">${value.toLocaleString('de-DE',{maximumFractionDigits:1})}</text></g>`).join('')}${points.map(point=>{const start=x(point.frequency-point.width/2),end=x(point.frequency+point.width/2),barWidth=Math.max(3,end-start-1),ofdm=point.width>10;return`<rect class="cable-channel ${ofdm?'ofdm':'qam'}" x="${start}" y="${y(point.power)}" width="${barWidth}" height="${y(minPower)-y(point.power)}"><title>Kanal ${esc(point.id)} · ${point.frequency.toLocaleString('de-DE')} MHz · ${point.power.toLocaleString('de-DE')} dBmV · ${esc(point.modulation)}</title></rect>`}).join('')}${ticks.map(value=>`<g><line x1="${x(value)}" y1="${height-bottom}" x2="${x(value)}" y2="${height-bottom+5}"/><text x="${x(value)}" y="${height-17}" text-anchor="middle">${value.toLocaleString('de-DE',{maximumFractionDigits:0})}</text></g>`).join('')}<text x="13" y="${top}" transform="rotate(-90 13 ${top})">dBmV</text></svg></div><div class="fritz-legend"><span><i class="qam"></i>SC-QAM / DOCSIS 3.0</span><span><i class="ofdm"></i>OFDM / DOCSIS 3.1</span></div><div class="axis-caption">Frequenz in MHz · Balkenbreite entspricht der Kanalbreite</div></section>`}
function cellRole(value){const role=String(value||'').toUpperCase();if(role.includes('PCC'))return{key:'PCC',label:'Primärer Funkträger',hint:'Hauptverbindung und Signalisierung',active:true};if(role.includes('SCC'))return{key:'SCC',label:'Zusätzlicher Funkträger',hint:'Gebündelte Zusatzkapazität',active:true};return{key:'N',label:'Nachbarzelle',hint:'Empfangbare alternative Zelle',active:false}}
function cellRoleGuide(cells){const count=key=>cells.filter(cell=>cellRole(cell.CellConnected).key===key).length;return`<section class="card carrier-guide"><div class="card-head"><div><h2>Aufbau der Mobilfunkverbindung</h2><p class="muted">So arbeiten Hauptträger, zusätzliche Träger und Nachbarzellen zusammen</p></div></div><div class="carrier-flow"><article class="primary"><span>PCC</span><div><strong>Primärer Funkträger</strong><small>Stellt die Hauptverbindung und Signalisierung bereit</small></div><b>${count('PCC')}</b></article><i>+</i><article class="secondary"><span>SCC</span><div><strong>Zusätzliche Funkträger</strong><small>Werden zur Steigerung von Bandbreite und Datenrate gebündelt</small></div><b>${count('SCC')}</b></article><i>↔</i><article class="neighbor"><span>N</span><div><strong>Nachbarzellen</strong><small>Stehen als Kandidaten für einen Zellwechsel zur Verfügung</small></div><b>${count('N')}</b></article></div><p class="carrier-summary"><strong>Aktuelle Verbindung:</strong> PCC und aktive SCC bilden gemeinsam die Datenverbindung. Nachbarzellen werden nur beobachtet und transportieren derzeit keinen Datenverkehr.</p></section>`}
function cellSignalChart(cells){const rows=cells.map(cell=>({...cell,rsrp:Number(cell.CellRsrp),pci:Number(cell.PhysicalId)})).filter(cell=>Number.isFinite(cell.rsrp)&&cell.rsrp<0);if(!rows.length)return'';const width=1000,height=290,left=58,right=18,top=18,bottom=58,min=-130,max=-70,plotWidth=width-left-right,slot=plotWidth/rows.length,y=value=>top+(max-Math.max(min,Math.min(max,value)))/(max-min)*(height-top-bottom);return`<section class="card fritz-spectrum-card"><div class="card-head"><div><h2>Funkzellen-Signalbild</h2><p class="muted">Empfangspegel der gemeldeten LTE- und 5G-Zellen nach Physical Cell ID</p></div><span class="live-pill good">Live-Zellen</span></div><div class="fritz-spectrum-wrap"><svg class="fritz-spectrum cellular-spectrum" viewBox="0 0 ${width} ${height}"><rect x="${left}" y="${top}" width="${plotWidth}" height="${height-top-bottom}"/>${[-130,-115,-100,-85,-70].map(value=>`<g><line class="grid" x1="${left}" y1="${y(value)}" x2="${width-right}" y2="${y(value)}"/><text x="${left-8}" y="${y(value)+4}" text-anchor="end">${value}</text></g>`).join('')}${rows.map((cell,index)=>{const x=left+index*slot+slot*.16,w=slot*.68,type=String(cell.CellType||'').toLowerCase(),role=cellRole(cell.CellConnected),connected=role.active;return`<rect class="cell-bar ${type.includes('5g')?'nr5g':'lte'} ${connected?'connected':''}" x="${x}" y="${y(cell.rsrp)}" width="${w}" height="${y(min)-y(cell.rsrp)}"><title>${esc(cell.CellType)} · PCI ${esc(cell.PhysicalId)} · ${cell.rsrp} dBm · ${esc(role.label)}</title></rect><text x="${x+w/2}" y="${height-36}" text-anchor="middle">${esc(cell.PhysicalId)}</text><text class="frequency" x="${x+w/2}" y="${height-21}" text-anchor="middle">${role.key}</text>`}).join('')}<text x="14" y="${top}" transform="rotate(-90 14 ${top})">RSRP in dBm</text></svg></div><div class="fritz-legend"><span><i class="cell-lte"></i>LTE</span><span><i class="cell-5g"></i>5G NR</span><span><i class="cell-connected"></i>aktuell verbundener Funkträger</span></div><div class="axis-caption">Physical Cell ID · PCC = Hauptträger · SCC = Zusatzträger · N = Nachbarzelle</div></section>`}
function cellularAccess(panel){const iface=instances('Device.Cellular.Interface.')[0]||{},cells=instances('Device.Cellular.Interface.1.X_AVM-DE_CellInfo.'),rsrp=Number(iface.RSRP),rsrq=Number(iface.RSRQ),rssi=Number(iface.RSSI),quality=rsrp>=-95?'good':rsrp>=-110?'warn':'bad';panel.innerHTML=`<div class="section-title"><div><h2>Mobilfunk-Anschluss</h2><p>Funkzugang, Zellumgebung, SIM und Mobilfunkmodem</p></div><span class="live-pill good">Live</span></div><div class="quality-grid">${metric('Zugang',String(iface.CurrentAccessTechnology||'–').replace('X_AVM-DE_',''))}${metric('RSRP',Number.isFinite(rsrp)?rsrp:'–','dBm',quality)}${metric('RSRQ',Number.isFinite(rsrq)?rsrq:'–','dB',rsrq>=-10?'good':rsrq>=-15?'warn':'bad')}${metric('RSSI',Number.isFinite(rssi)?rssi:'–','dBm',rssi>=-75?'good':rssi>=-90?'warn':'bad')}</div><div class="info-grid"><section class="card"><div class="card-head"><h3>Verbindung</h3>${status(iface.X_AVM_DE_Provider||iface['X_AVM-DE_Provider']||'Mobilfunk','good')}</div><dl class="detail-list"><div><dt>Provider</dt><dd>${esc(iface['X_AVM-DE_Provider']||'–')}</dd></div><div><dt>Netzkennung</dt><dd>${esc(iface['X_AVM-DE_PLMN']||'–')}</dd></div><div><dt>Zell-ID</dt><dd>${esc(iface['X_AVM-DE_CellId']||'–')}</dd></div><div><dt>Entfernung</dt><dd>${esc(iface['X_AVM-DE_Distance']||'–')} m</dd></div><div><dt>Maximal ↓ / ↑</dt><dd>${bitrate(iface.DownstreamMaxBitRate,'kbit')} / ${bitrate(iface.UpstreamMaxBitRate,'kbit')}</dd></div><div><dt>Modem-Firmware</dt><dd>${esc(iface['X_AVM-DE_SoftwareVersion']||'–')}</dd></div></dl></section><section class="card"><h3>SIM und Zugang</h3><dl class="detail-list"><div><dt>SIM-Status</dt><dd>${esc(iface['USIM.Status']||'–')}</dd></div><div><dt>ICCID</dt><dd class="mono">${esc(iface['USIM.ICCID']||'–')}</dd></div><div><dt>IMEI</dt><dd class="mono">${esc(iface.IMEI||'–')}</dd></div><div><dt>APN</dt><dd>${esc(iface['X_AVM-DE_LinkConfig.APN']||'–')}</dd></div><div><dt>Roaming</dt><dd>${bool(pv('Device.Cellular.RoamingEnabled','0'))?'Aktiv':'Aus'}</dd></div><div><dt>Modem-Uptime</dt><dd>${uptime(iface['X_AVM-DE_Uptime'])}</dd></div></dl></section></div>${cellRoleGuide(cells)}${cellSignalChart(cells)}<section class="card"><div class="card-head"><div><h2>Funkzellen</h2><p class="muted">${cells.length} aktuell gemeldete verbundene Träger und Nachbarzellen</p></div></div><div class="table-scroll"><table><thead><tr><th>Aufgabe</th><th>Technik</th><th>PCI</th><th>Zell-ID</th><th>RSRP</th><th>RSRQ</th><th>RSSI</th></tr></thead><tbody>${cells.map(cell=>{const role=cellRole(cell.CellConnected);return`<tr><td><span class="cell-role"><strong>${esc(role.label)}</strong><small>${role.key} · ${esc(role.hint)}</small></span></td><td>${esc(String(cell.CellType||'–').toUpperCase())}</td><td>${esc(cell.PhysicalId||'–')}</td><td class="mono">${esc(cell.CellId||'–')}</td><td>${cell.CellRsrp||'–'} dBm</td><td>${cell.CellRsrq||'–'} dB</td><td>${Number(cell.CellRssi)<0?cell.CellRssi+' dBm':'–'}</td></tr>`}).join('')}</tbody></table></div></section>${accessHistoryShell('Mobilfunk-Verlauf','RSRP, RSRQ und RSSI im zeitlichen Verlauf')}`;hydrateAccessHistory([{path:'Device.Cellular.Interface.1.RSRP',label:'RSRP',unit:'dBm',color:'#ffe900'},{path:'Device.Cellular.Interface.1.RSRQ',label:'RSRQ',unit:'dB',color:'#9b73b7'},{path:'Device.Cellular.Interface.1.RSSI',label:'RSSI',unit:'dBm',color:'#29c5b6'}])}
const MOBILE_BANDS={1:['2,1 GHz','FDD'],3:['1,8 GHz','FDD'],5:['850 MHz','FDD'],7:['2,6 GHz','FDD'],8:['900 MHz','FDD'],20:['800 MHz','FDD'],28:['700 MHz','FDD'],32:['1,5 GHz','SDL'],38:['2,6 GHz','TDD'],40:['2,3 GHz','TDD'],41:['2,5 GHz','TDD'],42:['3,5 GHz','TDD'],43:['3,7 GHz','TDD'],75:['1,5 GHz','SDL'],76:['1,5 GHz','SDL'],77:['3,7 GHz','TDD'],78:['3,5 GHz','TDD']}
function bandList(value){return String(value||'').split(',').map(item=>item.trim()).filter(item=>/^\d+$/.test(item))}
function bandCapabilityCard(title,description,supportedValue,enabledValue){const supported=bandList(supportedValue),enabled=bandList(enabledValue),automatic=String(enabledValue||'').toLowerCase()==='auto';if(!supported.length)return'';return`<article class="band-capability"><div class="band-capability-head"><div><h3>${esc(title)}</h3><p>${esc(description)}</p></div>${status(automatic?'Automatische Auswahl':`${enabled.length} aktiviert`,automatic?'good':'')}</div><div class="mobile-band-list">${supported.map(number=>{const info=MOBILE_BANDS[number]||['Frequenz nicht gemeldet',''],active=automatic||enabled.includes(number);return`<span class="${active?'active':''}" title="Band ${number} · ${info.join(' · ')} · ${active?'zur Auswahl freigegeben':'derzeit deaktiviert'}"><strong>${title.startsWith('5G')?'n':'B'}${number}</strong><small>${info[0]}${info[1]?` · ${info[1]}`:''}</small></span>`}).join('')}</div><div class="band-capability-legend"><i></i> Vom Modem unterstützt <i class="active"></i> derzeit zur Auswahl freigegeben</div></article>`}
function cellularBandCapabilities(iface){const cards=[bandCapabilityCard('LTE','4G-Funkbänder des eingebauten Modems',iface['X_AVM-DE_BandCapabilitiesLTE'],iface['X_AVM-DE_EnabledBandCapabilitiesLTE']),bandCapabilityCard('5G NSA','5G mit LTE als Ankerverbindung (Non-Standalone)',iface['X_AVM-DE_BandCapabilities5GNSA'],iface['X_AVM-DE_EnabledBandCapabilities5GNSA']),bandCapabilityCard('5G SA','Eigenständiges 5G ohne LTE-Anker (Standalone)',iface['X_AVM-DE_BandCapabilities5GSA'],iface['X_AVM-DE_EnabledBandCapabilities5GSA'])].filter(Boolean);return cards.length?`<section class="card mobile-capabilities"><div class="card-head"><div><h2>Unterstützte Mobilfunkbänder</h2><p class="muted">AVM Band Capabilities beschreiben die Hardwarefähigkeiten des Modems – nicht die aktuell verbundene Frequenz.</p></div><span class="live-pill good">Modem-Fähigkeiten</span></div><div class="mobile-band-grid">${cards.join('')}</div><div class="notice compact-notice"><strong>Zusammenhang:</strong> Die Box kann nur ein vom Modem unterstütztes und freigegebenes Band verwenden. Welches davon tatsächlich als PCC oder SCC verbunden ist, zeigt die Funkzellenübersicht darunter. FDD nutzt getrennte Frequenzen für Senden und Empfangen, TDD teilt eine Frequenz zeitlich auf; SDL dient nur zusätzlicher Downstream-Kapazität.</div></section>`:''}
const cellularAccessWithoutCapabilities=cellularAccess;
cellularAccess=function(panel){cellularAccessWithoutCapabilities(panel);const guide=panel.querySelector('.carrier-guide'),card=cellularBandCapabilities(instances('Device.Cellular.Interface.')[0]||{});if(guide&&card)guide.insertAdjacentHTML('afterend',card)}
function opticalLevel(name,value,min,max,goodMin,goodMax){if(!Number.isFinite(value))return'';const position=Math.max(0,Math.min(100,(value-min)/(max-min)*100)),quality=value>=goodMin&&value<=goodMax?'good':value>=goodMin-3&&value<=goodMax+3?'warn':'bad';return`<article class="optical-level ${quality}"><div class="optical-level-head"><div><small>${esc(name)}</small><strong>${value.toLocaleString('de-DE',{minimumFractionDigits:1,maximumFractionDigits:1})} <span>dBm</span></strong></div>${status(quality==='good'?'Optimal':quality==='warn'?'Grenzbereich':'Kritisch',quality==='good'?'good':quality==='bad'?'bad':'warn')}</div><div class="optical-scale"><div class="optical-zones"></div><i style="left:${position}%"><b>${value.toLocaleString('de-DE',{maximumFractionDigits:1})}</b></i></div><div class="optical-ticks"><span>${min}</span><span>Soll: ${goodMin} bis ${goodMax} dBm</span><span>${max}</span></div></article>`}
function opticalLevels(rx,tx){const cards=[opticalLevel('Optischer Empfangspegel (RX)',rx,-35,0,-27,-8),opticalLevel('Optischer Sendepegel (TX)',tx,-5,15,0,10)].filter(Boolean);return cards.length?`<section class="card optical-quality"><div class="card-head"><div><h2>Optische Pegel</h2><p class="muted">Aktuelle Messwerte mit Betriebs- und Grenzbereichen</p></div><span class="live-pill good">XGS-PON</span></div><div class="optical-level-grid">${cards.join('')}</div><div class="optical-legend"><span><i class="bad"></i>außerhalb</span><span><i class="warn"></i>Grenzbereich</span><span><i class="good"></i>optimaler Bereich</span></div></section>`:''}
function qualityLevel(name,value,unit,min,max,goodMin,goodMax){if(!Number.isFinite(value))return'';const position=Math.max(0,Math.min(100,(value-min)/(max-min)*100)),margin=(max-min)*.2,quality=value>=goodMin&&value<=goodMax?'good':value>=goodMin-margin&&value<=goodMax+margin?'warn':'bad',pct=n=>Math.max(0,Math.min(100,(n-min)/(max-min)*100)),g1=pct(goodMin),g2=pct(goodMax),w1=Math.max(0,g1-20),w2=Math.min(100,g2+20),gradient=`linear-gradient(90deg,#d74653 0 ${w1}%,#e0a126 ${w1}% ${g1}%,#2da66f ${g1}% ${g2}%,#e0a126 ${g2}% ${w2}%,#d74653 ${w2}% 100%)`;return`<article class="optical-level ${quality}"><div class="optical-level-head"><div><small>${esc(name)}</small><strong>${value.toLocaleString('de-DE',{minimumFractionDigits:1,maximumFractionDigits:1})} <span>${esc(unit)}</span></strong></div>${status(quality==='good'?'Optimal':quality==='warn'?'Grenzbereich':'Kritisch',quality==='good'?'good':quality==='bad'?'bad':'warn')}</div><div class="optical-scale"><div class="optical-zones" style="background:${gradient}"></div><i style="left:${position}%"><b>${value.toLocaleString('de-DE',{maximumFractionDigits:1})}</b></i></div><div class="optical-ticks"><span>${min}</span><span>Soll: ${goodMin} bis ${goodMax} ${esc(unit)}</span><span>${max}</span></div></article>`}
function qualityScalePanel(title,subtitle,items){const cards=items.map(item=>qualityLevel(...item)).filter(Boolean);return cards.length?`<section class="card optical-quality signal-quality"><div class="card-head"><div><h2>${esc(title)}</h2><p class="muted">${esc(subtitle)}</p></div><span class="live-pill good">Live</span></div><div class="optical-level-grid">${cards.join('')}</div><div class="optical-legend"><span><i class="bad"></i>kritisch</span><span><i class="warn"></i>Grenzbereich</span><span><i class="good"></i>optimal</span></div></section>`:''}
function fiberAccess(panel){const iface=instances('Device.Optical.Interface.')[0]||{},rx=Number(iface.OpticalSignalLevel)/10,tx=Number(iface.TransmitOpticalLevel)/10,stats=Object.fromEntries(Object.entries(iface).filter(([key])=>key.startsWith('Stats.'))),mode=iface['X_AVM-DE_BaseInfo.FiberModeStr']||'Fiber';panel.innerHTML=`<div class="section-title"><div><h2>Fiber-Anschluss</h2><p>Optische Schnittstelle, XGS-PON-Synchronisation und Qualitätsverlauf</p></div><span class="live-pill good">Live</span></div><div class="quality-grid">${metric('Status',iface.Status||'–','',String(iface.Status).toLowerCase()==='up'?'good':'bad')}${metric('Technik',mode)}${metric('Downstream',bitrate(stats['Stats.X_AVM-DE_ConnectionRateDs'],'kbit'))}${metric('Upstream',bitrate(stats['Stats.X_AVM-DE_ConnectionRateUs'],'kbit'))}</div>${opticalLevels(rx,tx)}<div class="info-grid"><section class="card"><div class="card-head"><h3>Optische Verbindung</h3>${status(iface.Status||'–',String(iface.Status).toLowerCase()==='up'?'good':'bad')}</div><dl class="detail-list"><div><dt>Modus</dt><dd>${esc(mode)}</dd></div><div><dt>Showtime</dt><dd>${uptime(Number(stats['Stats.X_AVM-DE_MinutesInShowtime'])*60)}</dd></div><div><dt>ONUs im Segment</dt><dd>${esc(stats['Stats.X_AVM-DE_ActiveOnusOnSegment']||'–')}</dd></div><div><dt>SFP-Firmware</dt><dd>${esc(iface['X_AVM-DE_BaseInfo.SfpModeFwVersion']||'–')}</dd></div><div><dt>Trainingszustand</dt><dd>${esc(stats['Stats.X_AVM-DE_BestTrainState']||'–')}</dd></div><div><dt>Letzte Änderung</dt><dd>${uptime(iface.LastChange)}</dd></div></dl></section><section class="card"><h3>Übertragung und Stabilität</h3><dl class="detail-list"><div><dt>Empfangen</dt><dd>${bytes(stats['Stats.BytesReceived'])}</dd></div><div><dt>Gesendet</dt><dd>${bytes(stats['Stats.BytesSent'])}</dd></div><div><dt>RX / TX Fehler</dt><dd>${esc(stats['Stats.ErrorsReceived']||'0')} / ${esc(stats['Stats.ErrorsSent']||'0')}</dd></div><div><dt>Verworfene Pakete</dt><dd>${esc(stats['Stats.DiscardPacketsReceived']||'0')} / ${esc(stats['Stats.DiscardPacketsSent']||'0')}</dd></div><div><dt>Resyncs</dt><dd>${esc(stats['Stats.X_AVM-DE_Resyncs']||'0')}</dd></div><div><dt>Retrains</dt><dd>${esc(stats['Stats.X_AVM-DE_SwRetrain']||'0')}</dd></div></dl></section></div>${accessHistoryShell('Optischer Pegelverlauf','Empfangs- und Sendepegel in dBm')}`;hydrateAccessHistory([{path:'Device.Optical.Interface.1.OpticalSignalLevel',label:'Empfang',unit:'dBm',scale:.1,color:'#ffe900'},{path:'Device.Optical.Interface.1.TransmitOpticalLevel',label:'Senden',unit:'dBm',scale:.1,color:'#9b73b7'}])}
function xponValue(suffix){const row=state.agent.parameters.find(item=>item.path.startsWith('Device.XPON.')&&item.path.endsWith(suffix));return row&&String(row.value)!==''?row.value:''}
function xponGroup(title,items){const rows=items.filter(([,value])=>value!==''&&value!==undefined&&value!==null);if(!rows.length)return'';return`<article><h3>${esc(title)}</h3><dl class="detail-list">${rows.map(([label,value,format])=>`<div><dt>${esc(label)}</dt><dd${/ID|Seriennummer|Zuordnung/.test(label)?' class="mono"':''}>${format==='bool'?status(bool(value)?'Aktiv':'Aus',bool(value)?'good':''):esc(value)}</dd></div>`).join('')}</dl></article>`}
function xponPeerCard(){const groups=[xponGroup('OLT-Gegenstelle',[['OLT-Vendor-ID',xponValue('X_AVM-DE_PortInfo.OltVendorId')],['Equipment-ID',xponValue('X_AVM-DE_PortInfo.OltEquipmentId')],['OLT-Version',xponValue('X_AVM-DE_PortInfo.OltVersion')],['PON-ID',xponValue('X_AVM-DE_PortInfo.PonId')]]),xponGroup('ONU-Aktivierung',[['PON-Modus',xponValue('ANI.1.PONMode')],['ONU-ID',xponValue('TC.ONUActivation.ONUID')],['ONU-Seriennummer',xponValue('TC.ONUActivation.SerialNumber')],['ONU-Instanzen',xponValue('ONUNumberOfEntries')],['ANI-Schnittstellen',xponValue('ANINumberOfEntries')]]),xponGroup('PON-Transport',[['FEC Downstream',xponValue('X_AVM-DE_PortInfo.FecDsEnabled'),'bool'],['FEC Upstream',xponValue('X_AVM-DE_PortInfo.FecUsEnabled'),'bool'],['GEM-Ports',xponValue('TC.GEM.PortNumberOfEntries')],['OMCI-/UNI-Zuordnung',xponValue('EthernetUNI.InterdomainID')]])].filter(Boolean);if(!groups.length)return'';return`<section class="card xpon-card"><div class="card-head"><div><h2>PON & Gegenstelle</h2><p class="muted">Vom ONU über USP gemeldete OLT-, Aktivierungs- und Transportdaten</p></div><span class="live-pill good">XPON</span></div><div class="xpon-grid">${groups.join('')}</div><div class="notice compact-notice">Die Angaben stammen aus der PON-Signalisierung beziehungsweise OMCI. Sie erlauben keine administrative Verbindung zum OLT.</div></section>`}
const fiberAccessWithoutXpon=fiberAccess;
fiberAccess=function(panel){fiberAccessWithoutXpon(panel);const card=xponPeerCard(),anchor=panel.querySelector('.optical-quality');if(card)(anchor||panel.querySelector('.quality-grid'))?.insertAdjacentHTML('afterend',card)};
function accessHistoryShell(title,subtitle){return`<section class="card fritz-spectrum-card access-history-card"><div class="card-head"><div><h2>${esc(title)}</h2><p class="muted">${esc(subtitle)} · letzte 24 Stunden</p></div><span class="live-pill good">Messpunkte</span></div><div id="access-history-chart"><div class="empty">Verlauf wird geladen …</div></div></section>`}
async function hydrateAccessHistory(specs){const endpoint=state.agent.agent.endpoint_id;try{const series=(await Promise.all(specs.map(async spec=>{const data=await api(`/api/agents/${encodeURIComponent(endpoint)}/history?path=${encodeURIComponent(spec.path)}&hours=24`);return{...spec,points:data.values.map(row=>({time:new Date(row.created_at).getTime(),value:Number(row.value)*(spec.scale||1)})).filter(point=>Number.isFinite(point.value))}}))).filter(item=>item.points.length>1);if(state.agent?.agent.endpoint_id!==endpoint||state.section!=='access')return;const target=$('#access-history-chart');if(!target)return;if(series.length)target.innerHTML=fritzTrendChart(series,24);else target.closest('.access-history-card')?.remove()}catch(error){const target=$('#access-history-chart');if(target)target.closest('.access-history-card')?.remove()}}
function fritzTrendChart(series,hours){const width=1000,height=300,left=58,right=18,top=18,bottom=48,all=series.flatMap(item=>item.points.map(point=>point.value)),min=Math.floor(Math.min(...all)-1),max=Math.ceil(Math.max(...all)+1),range=Math.max(1,max-min),start=Date.now()-hours*3600000,x=time=>left+(time-start)/(hours*3600000)*(width-left-right),y=value=>top+(max-value)/range*(height-top-bottom),ticks=[0,.25,.5,.75,1];return`<div class="fritz-spectrum-wrap"><svg class="fritz-spectrum access-trend" viewBox="0 0 ${width} ${height}"><rect x="${left}" y="${top}" width="${width-left-right}" height="${height-top-bottom}"/>${ticks.map(t=>`<g><line class="grid" x1="${left}" y1="${top+t*(height-top-bottom)}" x2="${width-right}" y2="${top+t*(height-top-bottom)}"/><text x="${left-8}" y="${top+t*(height-top-bottom)+4}" text-anchor="end">${(max-t*range).toLocaleString('de-DE',{maximumFractionDigits:1})}</text><text x="${left+t*(width-left-right)}" y="${height-17}" text-anchor="middle">${new Date(start+t*hours*3600000).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}</text></g>`).join('')}${series.map(item=>`<polyline style="stroke:${item.color}" points="${item.points.map(point=>`${x(point.time)},${y(point.value)}`).join(' ')}"/>`).join('')}</svg></div><div class="fritz-legend">${series.map(item=>`<span><i style="background:${item.color}"></i>${esc(item.label)} (${esc(item.unit)})</span>`).join('')}</div><div class="axis-caption">Zeitachse · tatsächliche Messpunkte und Werte</div>`}
function renderAccess(panel){const type=accessType();if(type==='Cable'){const info=instances('Device.DOCSIS.Interface.'),down=instances('Device.DOCSIS.DownstreamChannel.').filter(x=>Number(x.Frequency)>0),up=instances('Device.DOCSIS.UpstreamChannel.').filter(x=>Number(x.Width)>0);panel.innerHTML=`<div class="section-title"><div><h2>Cable-Anschluss</h2><p>DOCSIS-Status, Frequenzplan und Kanalqualität</p></div><span class="live-pill good">Live</span></div><div class="quality-grid">${metric('Status',info[0]?.['ConnectivityStatus.Value']||'–','',info[0]?.['ConnectivityStatus.Value']==='Operational'?'good':'bad')}${metric('DOCSIS',info[0]?.DOCSISVersion||'–')}${metric('Resets',info[0]?.['ConnectivityStatus.Resets']||'0')}${metric('CMTS',info[0]?.CMTSAddress||'–')}</div>${cablePowerChart(down)}${channelTable('Downstream',down,false)}${channelTable('Upstream',up,true)}`;return}if(type==='DSL'){const line=instances('Device.DSL.Line.')[0]||{},channel=instances('Device.DSL.Channel.')[0]||{},snr=Number(line.DownstreamNoiseMargin);panel.innerHTML=`<div class="section-title"><div><h2>DSL-Anschluss</h2><p>Leitungszustand und vollständige Trägeranalyse</p></div><span class="live-pill good">Live</span></div><div class="quality-grid">${metric('Status',line.Status||channel.Status||'–','',String(line.Status||channel.Status).toLowerCase()==='up'?'good':'bad')}${metric('Downstream',bitrate(channel.DownstreamCurrRate||line.DownstreamMaxBitRate,'kbit'))}${metric('Upstream',bitrate(channel.UpstreamCurrRate||line.UpstreamMaxBitRate,'kbit'))}${metric('SNR-Marge ↓',Number.isFinite(snr)?(snr/10).toLocaleString('de-DE',{minimumFractionDigits:1,maximumFractionDigits:1}):'–','dB')}</div>${dslFritzSpectrum()}${dslSpectrumCards()}`;return}if(type==='Mobilfunk'){cellularAccess(panel);return}if(type==='Fiber'){fiberAccess(panel);return}const rows=state.agent.parameters.filter(item=>item.path.startsWith('Device.IP.Interface.'));panel.innerHTML=`<div class="section-title"><div><h2>WAN-Anschluss</h2><p>Alle verfügbaren Mess- und Statuswerte</p></div><span class="live-pill good">Live</span></div>${parameterTable(rows)}`}
function channelTable(title,rows,upstream){return`<section class="card"><div class="card-head"><div><h2>${title}</h2><p class="muted">${rows.length} aktive Kanäle</p></div></div><div class="table-scroll"><table><thead><tr><th>Kanal</th><th>Technik</th><th>Frequenz</th><th>Breite</th>${upstream?'':'<th>Modulation</th><th>Pegel</th>'}</tr></thead><tbody>${rows.map(row=>{const ofdm=Number(row.Width)>10000000,power=Number(row.Power);return`<tr><td>${esc(row.ID||row.id)}</td><td>${status(ofdm?'DOCSIS 3.1 / OFDM':'SC-QAM',ofdm?'good':'')}</td><td>${(Number(row.Frequency)/1e6).toLocaleString('de-DE',{maximumFractionDigits:3})} MHz</td><td>${(Number(row.Width)/1e6).toLocaleString('de-DE',{maximumFractionDigits:2})} MHz</td>${upstream?'':`<td>${esc(row.Modulation||'–')}</td><td>${Number.isFinite(power)?(power/10).toLocaleString('de-DE',{minimumFractionDigits:1,maximumFractionDigits:1}):'–'} dBmV</td>`}</tr>`}).join('')}</tbody></table></div></section>`}

function renderWifi(panel){const radios=instances('Device.WiFi.Radio.'),ssids=instances('Device.WiFi.SSID.'),hosts=instances('Device.Hosts.Host.').filter(host=>bool(host.Active)&&String(host.Layer1Interface||'').includes('WiFi'));panel.innerHTML=`<div class="section-title"><div><h2>WLAN</h2><p>Funknetze, Radios und aktuell verbundene Clients</p></div><span class="live-pill good">Live</span></div><div class="radio-grid">${radios.map(radio=>`<section class="card radio-card"><div class="card-head"><div><h3>${esc(radio.OperatingFrequencyBand||`Radio ${radio.id}`)}</h3><p class="muted">Wi-Fi ${esc(radio.OperatingStandards||'–')}</p></div>${status(bool(radio.Enable??'1')?'Aktiv':'Aus',bool(radio.Enable??'1')?'good':'')}</div><div class="quality-grid compact">${metric('Kanal',radio.Channel||'–')}${metric('Automatik',bool(radio.AutoChannelEnable)?'An':'Aus')}${metric('Sendeleistung',radio.TransmitPower||'–','%')}${metric('Auslastung',radio.ChannelUtilization??'–','%')}</div></section>`).join('')}</div><section class="card"><div class="card-head"><div><h2>SSID-Instanzen</h2><p class="muted">${ssids.length} Funknetze</p></div></div><div class="table-scroll"><table><thead><tr><th>SSID</th><th>Status</th><th>BSSID</th><th>Radio</th></tr></thead><tbody>${ssids.map(ssid=>`<tr><td><strong>${esc(ssid.SSID||'–')}</strong></td><td>${status(bool(ssid.Enable)?'Aktiv':'Aus',bool(ssid.Enable)?'good':'')}</td><td class="mono">${esc(ssid.BSSID||'–')}</td><td class="mono">${esc(ssid.LowerLayers||'–')}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="card-head"><div><h2>Verbundene WLAN-Clients</h2><p class="muted">${hosts.length} aktuell aktive Geräte</p></div><span class="live-pill good">Live</span></div>${hosts.length?`<div class="client-grid">${hosts.map(host=>`<article class="client-card"><div><strong>${esc(host.HostName||host.X_AVM_DE_FriendlyName||'Unbekannt')}</strong><small>${esc(host.IPAddress||'–')}</small></div><span class="mono">${esc(host.PhysAddress||'–')}</span><small>${esc(host.Layer1Interface||'WLAN')}</small></article>`).join('')}</div>`:'<div class="empty">Keine aktiven WLAN-Clients im aktuellen Datenbestand.</div>'}</section>`}

function renderNetwork(panel){const ports=instances('Device.Ethernet.Interface.'),interfaces=instances('Device.IP.Interface.');panel.innerHTML=`<div class="section-title"><div><h2>Netzwerk & Traffic</h2><p>Ethernet-Ports und Schnittstellenzähler</p></div><span class="live-pill good">Live</span></div><section class="card"><div class="card-head"><h2>Ethernet-Ports</h2></div><div class="table-scroll"><table><thead><tr><th>Port</th><th>Status</th><th>Aktuell</th><th>Maximum</th><th>MAC</th></tr></thead><tbody>${ports.map(port=>`<tr><td><strong>${esc(port.Name||`Port ${port.id}`)}</strong></td><td>${status(Number(port.CurrentBitRate)>0?'Verbunden':'Getrennt',Number(port.CurrentBitRate)>0?'good':'')}</td><td>${bitrate(port.CurrentBitRate||0,'mbit')}</td><td>${bitrate(port.MaxBitRate,'mbit')}</td><td class="mono">${esc(port.MACAddress||'–')}</td></tr>`).join('')}</tbody></table></div></section><div class="info-grid">${interfaces.map(iface=>`<section class="card"><div class="card-head"><h3>${esc(iface.Name||`IP-Interface ${iface.id}`)}</h3>${status(iface.Status||'–',String(iface.Status).toLowerCase()==='up'?'good':'')}</div><div class="quality-grid compact">${metric('Empfangen',bytes(iface['Stats.BytesReceived']))}${metric('Gesendet',bytes(iface['Stats.BytesSent']))}${metric('RX-Fehler',iface['Stats.ErrorsReceived']||'0')}${metric('TX-Fehler',iface['Stats.ErrorsSent']||'0')}</div></section>`).join('')}</div>`}

function isMetricParameter(item){return Number.isFinite(Number(item.value))&&/(Usage|Utilization|Bytes|Packets|Power|SNR|RSRP|RSRQ|Rate|Latency|Errors|Timeouts?|UpTime|Free|Total|Current|Temperature|Signal|Noise|Quality|Speed|Load|Count)$/i.test(item.path)}
async function renderHistory(panel){const candidates=state.agent.parameters.filter(isMetricParameter).slice(0,1000);panel.innerHTML=`<div class="section-title"><div><h2>Messwerte & Diagramme</h2><p>Zeitreihen aus Notify-Nachrichten und veränderten Messwertabfragen</p></div><span class="live-pill good">Live</span></div><section class="card"><div class="history-toolbar"><label>Messwert<select id="history-path">${candidates.map(item=>`<option value="${esc(item.path)}">${esc(item.path.replace('Device.',''))}</option>`).join('')}</select></label><label>Zeitraum<select id="history-hours"><option value="1">1 Stunde</option><option value="6">6 Stunden</option><option value="24" selected>24 Stunden</option><option value="168">7 Tage</option></select></label></div><div id="history-chart"><div class="empty">Lade Verlauf …</div></div></section>`;if(!candidates.length){$('#history-chart').innerHTML='<div class="empty">Noch keine numerischen Messwerte vorhanden.</div>';return}$('#history-path').onchange=loadHistory;$('#history-hours').onchange=loadHistory;if(state.historyPath&&candidates.some(item=>item.path===state.historyPath))$('#history-path').value=state.historyPath;state.historyPath=null;loadHistory()}
async function loadHistory(){const path=$('#history-path')?.value;if(!path)return;const hours=Number($('#history-hours').value),data=await api(`/api/agents/${encodeURIComponent(state.agent.agent.endpoint_id)}/history?path=${encodeURIComponent(path)}&hours=${hours}`),points=data.values.map(row=>({time:new Date(row.created_at).getTime(),value:Number(row.value)})).filter(x=>Number.isFinite(x.value));$('#history-chart').innerHTML=lineChart(points,hours)}
function lineChart(points,hours){if(points.length<2)return'<div class="empty">Für diesen Wert liegen im gewählten Zeitraum noch nicht genügend ValueChange-Meldungen vor.</div>';const width=900,height=300,left=64,right=18,top=20,bottom=44,min=Math.min(...points.map(x=>x.value)),max=Math.max(...points.map(x=>x.value)),start=Date.now()-hours*3600000,range=Math.max(1,max-min),coords=points.map(p=>`${left+(p.time-start)/(hours*3600000)*(width-left-right)},${top+(max-p.value)/range*(height-top-bottom)}`).join(' ');const ticks=[0,.25,.5,.75,1];return`<svg class="line-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Live-Werteverlauf"><line x1="${left}" y1="${top}" x2="${left}" y2="${height-bottom}"/><line x1="${left}" y1="${height-bottom}" x2="${width-right}" y2="${height-bottom}"/>${ticks.map(t=>`<g><line x1="${left}" y1="${top+t*(height-top-bottom)}" x2="${width-right}" y2="${top+t*(height-top-bottom)}" class="grid"/><text x="${left-10}" y="${top+t*(height-top-bottom)+4}" text-anchor="end">${(max-t*range).toLocaleString('de-DE',{maximumFractionDigits:1})}</text><text x="${left+t*(width-left-right)}" y="${height-12}" text-anchor="middle">${new Date(start+t*hours*3600000).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}</text></g>`).join('')}<polyline points="${coords}"/></svg>`}

function isPercentParameter(row){const value=Number(row.value);return Number.isFinite(value)&&value>=0&&value<=100&&/(Percent|Percentage|Usage|Utilization|TransmitPower)$/i.test(row.path)}
function csvValues(value){const parts=String(value??'').split(',').map(x=>x.trim()).filter(x=>x!=='');if(parts.length<4)return null;const numbers=parts.map(Number);return numbers.every(Number.isFinite)?numbers:null}
function miniSeries(values,path){const valid=values.map((value,index)=>({value,index})).filter(point=>Number.isFinite(point.value)&&(!/HLOG/i.test(path)||point.value<1000));if(valid.length<2)return`<span class="series-count">${values.length} Messpunkte</span>`;const min=Math.min(...valid.map(x=>x.value)),max=Math.max(...valid.map(x=>x.value)),range=Math.max(1,max-min),width=220,height=42,points=valid.map(point=>`${point.index/(values.length-1)*width},${height-(point.value-min)/range*(height-4)-2}`).join(' ');return`<div class="mini-series"><svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none"><polyline points="${points}"/></svg><small>${values.length} Messpunkte · ${min.toLocaleString('de-DE')} bis ${max.toLocaleString('de-DE')}</small></div>`}
function universalValue(row){if(Number.isFinite(Number(row.value))&&/(BitRate|PHYRate|ThroughputCapacity|ConnectionRate)$/i.test(row.path)){const input=/^Device\.(Ethernet|WiFi|IEEE1905)\./.test(row.path)?'mbit':'kbit';return`<span>${esc(bitrate(row.value,input))}</span>`}if(isPercentParameter(row)){const value=Math.max(0,Math.min(100,Number(row.value)));return`<div class="universal-percent"><div><span style="width:${value}%"></span></div><strong>${value.toLocaleString('de-DE')} %</strong></div>`}if(['true','false','0','1'].includes(String(row.value).toLowerCase())&&/(Enable|Enabled|Active|Upstream|Persistent|Auto|Status)$/i.test(row.path))return status(bool(row.value)?'Aktiv':'Aus',bool(row.value)?'good':'');const series=csvValues(row.value);if(series)return miniSeries(series,row.path);if(String(row.value).includes(',')){const values=String(row.value).split(',').map(x=>x.trim()).filter(Boolean);return`<div class="value-tags">${values.slice(0,12).map(value=>`<span>${esc(value.replace(/^Device\./,''))}</span>`).join('')}${values.length>12?`<small>+${values.length-12} weitere</small>`:''}</div>`}return`<span>${esc(row.value)}</span>`}
function schemaPattern(path){return new RegExp('^'+path.replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replace(/\\\{i\\\}/g,'\\d+')+'$')}
function parameterSchema(path){return state.schema.find(item=>item.kind==='parameter'&&schemaPattern(item.path).test(path))}
function schemaLabel(item){return String(item||'').replace(/^PARAM_/,'').replaceAll('_',' ')}
function parameterTable(rows){return rows.length?`<div class="table-scroll"><table><thead><tr><th>Pfad</th><th>Wert</th><th>Eigenschaften</th><th>Stand</th><th></th></tr></thead><tbody>${rows.map(row=>{const schema=parameterSchema(row.path),write=schema&&/READ_WRITE|WRITE_ONLY/.test(schema.access);return`<tr data-param-path="${esc(row.path)}"><td class="mono model-path">${esc(row.path)}</td><td class="value-cell">${universalValue(row)}</td><td><small>${schema?`${esc(schemaLabel(schema.value_type))} · ${esc(schemaLabel(schema.access))}`:'noch nicht klassifiziert'}</small></td><td data-updated>${fmt(row.updated_at)}</td><td><div class="model-row-actions"><button class="model-icon-button" data-read-path="${esc(row.path)}" title="Jetzt lesen">↻</button>${isMetricParameter(row)?`<button class="model-chart-button" data-chart-path="${esc(row.path)}" title="Als Diagramm anzeigen">⌁</button>`:''}${write&&state.session.role!=='viewer'?`<button class="model-icon-button edit" data-edit-path="${esc(row.path)}" title="Wert ändern">✎</button>`:''}</div></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Keine Parameter vorhanden.</div>'}
function modelCategory(path){const part=path.split('.')[1]||'Sonstige';return part}
function preparedParameterPath(path){const exact=new Set(['Device.DeviceInfo.ModelName','Device.DeviceInfo.SoftwareVersion','Device.DeviceInfo.HardwareVersion','Device.DeviceInfo.SerialNumber','Device.DeviceInfo.UpTime','Device.DeviceInfo.ProcessStatus.CPUUsage','Device.DeviceInfo.MemoryStatus.Total','Device.DeviceInfo.MemoryStatus.Free','Device.Cellular.Interface.1.RSRP','Device.Cellular.Interface.1.RSRQ','Device.Cellular.Interface.1.RSSI','Device.Cellular.Interface.1.X_AVM-DE_BandCapabilitiesLTE','Device.Cellular.Interface.1.X_AVM-DE_EnabledBandCapabilitiesLTE','Device.Cellular.Interface.1.X_AVM-DE_BandCapabilities5GNSA','Device.Cellular.Interface.1.X_AVM-DE_EnabledBandCapabilities5GNSA','Device.Cellular.Interface.1.X_AVM-DE_BandCapabilities5GSA','Device.Cellular.Interface.1.X_AVM-DE_EnabledBandCapabilities5GSA','Device.Optical.Interface.1.OpticalSignalLevel','Device.Optical.Interface.1.TransmitOpticalLevel']);if(exact.has(path)||path.startsWith('Device.XPON.'))return true;return /^Device\.Cellular\.Interface\.1\.X_AVM-DE_CellInfo\.\d+\./.test(path)||/^Device\.DOCSIS\.(DownstreamChannel|UpstreamChannel)\.\d+\./.test(path)||/^Device\.DSL\.Line\.1\.(SNRMpbds|SNRMpbus|TestParams\.(HLOGpsds|HLOGpsus|QLNpsds|QLNpsus|LATNds|LATNus))$/.test(path)}
function unpreparedParameters(){return state.agent.parameters.filter(item=>!preparedParameterPath(item.path))}
function renderParameters(panel){const categories=[...new Set(state.agent.parameters.map(item=>modelCategory(item.path)))].sort(),commands=state.schema.filter(x=>x.kind==='command'),events=state.schema.filter(x=>x.kind==='event'),writable=state.schema.filter(x=>x.kind==='parameter'&&/READ_WRITE|WRITE_ONLY/.test(x.access));panel.innerHTML=`<section class="card"><div class="card-head"><div><h2>Vollständiges USP-Datenmodell</h2><p class="muted">${state.agent.parameters.length.toLocaleString('de-DE')} Werte in ${categories.length} Modellbereichen</p></div><div class="section-actions"><span class="live-pill good">Live</span><button class="secondary" id="sync-model">Modell synchronisieren</button></div></div><div class="model-summary model-summary-wide"><div><strong>${state.agent.parameters.filter(isMetricParameter).length.toLocaleString('de-DE')}</strong><small>diagrammfähige Messwerte</small></div><div><strong>${state.agent.parameters.filter(isPercentParameter).length.toLocaleString('de-DE')}</strong><small>Prozentwerte mit Balken</small></div><div><strong>${writable.length.toLocaleString('de-DE')}</strong><small>schreibbare Parameter</small></div><div><strong>${commands.length.toLocaleString('de-DE')}</strong><small>verfügbare Befehle</small></div><div><strong>${events.length.toLocaleString('de-DE')}</strong><small>Ereignistypen</small></div></div>${state.schema.length?'':`<div class="notice">Die Werte sind vollständig verfügbar. Für typisierte Eingaben, exakte Schreibrechte und den Aktionskatalog bitte einmal das Modell synchronisieren.</div>`}<div class="toolbar model-toolbar"><select id="parameter-category"><option value="">Alle Bereiche</option>${categories.map(name=>`<option value="${esc(name)}">Device.${esc(name)}.</option>`).join('')}</select><input id="parameter-search" placeholder="Pfad oder Wert durchsuchen …"></div><div id="parameter-table"></div></section>${commands.length?`<section class="card"><details><summary><strong>Verfügbare USP-Befehle (${commands.length})</strong></summary><div class="command-grid">${commands.map(cmd=>`<button class="command-item" data-command="${esc(cmd.path)}"><strong>${esc(cmd.path)}</strong><small>${esc(schemaLabel(cmd.value_type))} · ${(cmd.metadata.input_args||[]).length} Eingaben</small></button>`).join('')}</div></details></section>`:''}`;$('#parameter-search').oninput=drawParameters;$('#parameter-category').onchange=drawParameters;$('#sync-model').onclick=syncModel;drawParameters();bindModelCommands()}
function drawParameters(){const query=($('#parameter-search')?.value||'').toLowerCase(),category=$('#parameter-category')?.value||'',rows=unpreparedParameters().filter(item=>(!category||modelCategory(item.path)===category)&&(item.path.toLowerCase().includes(query)||String(item.value).toLowerCase().includes(query))).slice(0,1500);$('#parameter-table').innerHTML=parameterTable(rows);bindModelRows()}
const renderParametersWithRawCount=renderParameters;
renderParameters=function(panel){renderParametersWithRawCount(panel);const remaining=unpreparedParameters(),heading=panel.querySelector('.card-head h2'),description=panel.querySelector('.card-head p'),summary=panel.querySelectorAll('.model-summary strong');if(heading)heading.textContent='Weitere USP-Parameter';if(description)description.textContent=`${remaining.length.toLocaleString('de-DE')} noch nicht anderweitig aufbereitete Werte. Bereits visualisierte Rohwerte werden hier nicht doppelt angezeigt.`;if(summary[0])summary[0].textContent=remaining.filter(isMetricParameter).length.toLocaleString('de-DE');if(summary[1])summary[1].textContent=remaining.filter(isPercentParameter).length.toLocaleString('de-DE')}
function bindModelRows(){$$('[data-chart-path]').forEach(button=>button.onclick=()=>{state.historyPath=button.dataset.chartPath;state.section='history';renderAgentSection()});$$('[data-read-path]').forEach(button=>button.onclick=()=>readModelValue(button.dataset.readPath));$$('[data-edit-path]').forEach(button=>button.onclick=()=>editModelValue(button.dataset.editPath))}
async function readModelValue(path){try{await api(`/api/agents/${encodeURIComponent(state.agent.agent.endpoint_id)}/jobs`,{method:'POST',body:JSON.stringify({action:'get',payload:{paths:[path],max_depth:0}})});toast('Aktueller Wert wurde angefordert')}catch(error){toast(error.message,true)}}
function typedInput(schema,value){if(schema?.value_type==='PARAM_BOOLEAN')return`<select name="value"><option value="true" ${bool(value)?'selected':''}>Aktiv</option><option value="false" ${!bool(value)?'selected':''}>Aus</option></select>`;const numeric=/PARAM_(DECIMAL|INT|LONG|UNSIGNED_INT|UNSIGNED_LONG)/.test(schema?.value_type||'');return`<input name="value" value="${esc(value)}" ${numeric?'type="number" step="any"':'type="text"'} required>`}
function editModelValue(path){const row=state.agent.parameters.find(x=>x.path===path),schema=parameterSchema(path),split=path.lastIndexOf('.')+1,dialog=$('#model-dialog');dialog.innerHTML=`<form method="dialog" id="model-edit-form"><div class="card-head"><div><span class="eyebrow">USP SET</span><h2>Wert ändern</h2></div><button type="button" data-close class="secondary">×</button></div><p class="mono model-dialog-path">${esc(path)}</p><label>Neuer Wert${typedInput(schema,row?.value||'')}</label><div class="notice">Datentyp: ${esc(schemaLabel(schema?.value_type||'unbekannt'))}. Die Änderung wird erst nach Ihrer Sicherheitsbestätigung an das Gerät gesendet.</div><div class="actions"><button type="button" data-close class="secondary">Abbrechen</button><button type="submit" class="primary">Prüfen und senden</button></div></form>`;dialog.showModal();$$('[data-close]').forEach(button=>button.onclick=()=>dialog.close());$('#model-edit-form').onsubmit=async event=>{event.preventDefault();const value=new FormData(event.currentTarget).get('value');if(!confirm(`${path} wirklich auf „${value}“ setzen?`))return;try{await api(`/api/agents/${encodeURIComponent(state.agent.agent.endpoint_id)}/jobs`,{method:'POST',body:JSON.stringify({action:'set',payload:{object_path:path.slice(0,split),parameters:[{name:path.slice(split),value,required:true}]}})});dialog.close();toast('Änderung wurde sicher an das Gerät gesendet')}catch(error){toast(error.message,true)}}}
async function syncModel(){try{await api(`/api/agents/${encodeURIComponent(state.agent.agent.endpoint_id)}/jobs`,{method:'POST',body:JSON.stringify({action:'get_supported_dm',payload:{paths:['Device.'],first_level_only:false}})});toast('Vollständiges Datenmodell wurde angefordert – die Metadaten erscheinen nach der Antwort')}catch(error){toast(error.message,true)}}
function bindModelCommands(){$$('[data-command]').forEach(button=>button.onclick=()=>{state.section='actions';renderAgentSection();const input=$('[name="command"]');if(input){input.value=button.dataset.command;input.scrollIntoView({behavior:'smooth',block:'center'})}})}
function jobs(rows){return`<section class="card"><div class="card-head"><h2>USP-Aufträge</h2></div>${rows?.length?`<div class="table-scroll"><table><thead><tr><th>Status</th><th>Aktion</th><th>Zeit</th><th>Ergebnis</th></tr></thead><tbody>${rows.map(job=>`<tr><td>${status(job.state,job.state==='complete'?'good':job.state==='failed'?'bad':'warn')}</td><td>${esc(job.action)}</td><td>${fmt(job.created_at)}</td><td>${job.error?`<span class="bad-text">${esc(job.error)}</span>`:`<details><summary>Details</summary><pre class="raw">${esc(JSON.stringify(detail(job.response_json||job.request_json),null,2))}</pre></details>`}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Noch keine USP-Aufträge.</div>'}</section>`}
function actions(){const disabled=state.session.role==='viewer'?'disabled':'';return`<div class="notice">Leseaktionen sind jederzeit möglich. Änderungen und Befehle benötigen Operator- oder Administratorrechte und eine Bestätigung.</div><div class="action-grid"><form class="action-card" data-action="get"><h3>Parameter lesen</h3><label>Pfade<textarea name="paths">Device.</textarea></label><label>Maximale Tiefe<input name="max_depth" type="number" min="0" value="0"></label><button class="primary">Abrufen</button></form><form class="action-card" data-action="get_supported_dm"><h3>Datenmodell abfragen</h3><label>Objektpfade<textarea name="paths">Device.</textarea></label><button class="primary">Abfragen</button></form><form class="action-card" data-action="get_instances"><h3>Instanzen abfragen</h3><label>Objektpfade<textarea name="paths">Device.</textarea></label><button class="primary">Abfragen</button></form><form class="action-card" data-action="set"><h3>Werte setzen</h3><label>Objektpfad<input name="object_path" placeholder="Device.WiFi.SSID.1."></label><label>Parameter (Name=Wert)<textarea name="parameters"></textarea></label><button class="primary" ${disabled}>Setzen</button></form><form class="action-card" data-action="add"><h3>Instanz anlegen</h3><label>Objektpfad<input name="object_path" placeholder="Device.LocalAgent.Subscription."></label><label>Parameter (Name=Wert)<textarea name="parameters"></textarea></label><button class="primary" ${disabled}>Anlegen</button></form><form class="action-card" data-action="delete"><h3>Instanz löschen</h3><label>Objektpfade<textarea name="paths"></textarea></label><button class="danger" ${disabled}>Löschen</button></form><form class="action-card" data-action="operate"><h3>Befehl ausführen</h3><label>Command<input name="command" placeholder="Device.IP.Diagnostics.IPPing()"></label><label>Argumente als JSON<textarea name="input_args">{}</textarea></label><button class="danger" ${disabled}>Ausführen</button></form></div>`}
const lines=value=>String(value||'').split('\n').map(x=>x.trim()).filter(Boolean),parameters=value=>lines(value).map(line=>{const index=line.indexOf('=');if(index<1)throw Error(`Ungültiger Parameter: ${line}`);return{name:line.slice(0,index).trim(),value:line.slice(index+1).trim(),required:true}});
function bindActions(){$$('[data-action]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const action=form.dataset.action;try{const data=new FormData(form),payload={};if(['get','get_instances','get_supported_dm','delete'].includes(action))payload.paths=lines(data.get('paths'));if(action==='get')payload.max_depth=Number(data.get('max_depth')||0);if(['set','add'].includes(action)){payload.object_path=data.get('object_path').trim();payload.parameters=parameters(data.get('parameters'))}if(action==='operate'){payload.command=data.get('command').trim();payload.input_args=JSON.parse(data.get('input_args')||'{}')}if(['set','add','delete','operate'].includes(action)&&!confirm(`USP-Aktion „${action}“ wirklich senden?`))return;const result=await api(`/api/agents/${encodeURIComponent(state.agent.agent.endpoint_id)}/jobs`,{method:'POST',body:JSON.stringify({action,payload})});toast(`Auftrag gesendet: ${result.msg_id}`)}catch(error){toast(error.message,true)}})}

