  return{score,label:score>=85?'Sehr gut':score>=68?'Gut':score>=48?'Ausreichend':score>=28?'Schwach':'Kritisch',level:score>=85?'excellent':score>=68?'good':score>=48?'fair':score>=28?'weak':'critical'};
