function startClientPolling(){clearInterval(state.clientPoll);const refresh=()=>{if(!state.selectedClient||!state.agent)return;const host=instances('Device.Hosts.Host.').find(item=>String(item.id)===state.selectedClient),link=host&&associatedClient(host);if(!host||!link)return;api(`/api/agents/${encodeURIComponent(state.agent.agent.endpoint_id)}/jobs`,{method:'POST',body:JSON.stringify({action:'get',payload:{paths:[`Device.Hosts.Host.${host.id}.`,`${link.base}.`],max_depth:0}})}).catch(()=>{})};refresh();state.clientPoll=setInterval(refresh,4000)}

