function meshIcon(kind){return kind==='router'?'▣':kind==='mesh'?'◆':kind==='WLAN'?'⌁':kind==='Powerline'?'ϟ':'↔'}
function fritzDeviceSymbol(model='FRITZ!Box'){
  const name=String(model).toLowerCase();
  if(name.includes('smart gateway'))return`<span class="fritz-device-symbol gateway"><svg viewBox="0 0 64 64" aria-hidden="true"><rect x="18" y="4" width="28" height="56" rx="9"/><path d="M23 13h18M23 19h18"/><circle cx="25" cy="48" r="2"/><circle cx="32" cy="48" r="2"/><circle cx="39" cy="48" r="2"/></svg></span>`;
  if(name.includes('repeater'))return`<span class="fritz-device-symbol repeater"><svg viewBox="0 0 64 64" aria-hidden="true"><rect x="19" y="5" width="26" height="54" rx="8"/><path d="M25 18c4-4 10-4 14 0M28 22c2-2 6-2 8 0"/><circle cx="32" cy="31" r="2"/><path d="M25 48h14"/></svg></span>`;
  if(name.includes('powerline'))return`<span class="fritz-device-symbol powerline"><svg viewBox="0 0 64 64" aria-hidden="true"><rect x="12" y="12" width="40" height="42" rx="8"/><path d="M24 7v7M40 7v7M35 20l-9 15h8l-5 10"/></svg></span>`;
  return`<span class="fritz-device-symbol box"><svg viewBox="0 0 64 64" aria-hidden="true"><path d="M6 22c0-8 7-14 15-14h22c8 0 15 6 15 14v21c0 7-6 12-13 12H19C12 55 6 50 6 43Z"/><path class="accent" d="M7 24c9 3 16 1 23-5 8-7 17-8 27-5v8c-9-3-16-1-23 5-8 7-17 8-27 5Z"/><circle cx="20" cy="44" r="2"/><circle cx="28" cy="44" r="2"/><circle cx="36" cy="44" r="2"/><circle cx="44" cy="44" r="2"/></svg></span>`
}
function meshRate(link,metric){const down=link?.macRx??metric.capacityRx,up=link?.macTx??metric.capacityTx;if(down==null&&up==null)return'Rate nicht gemeldet';return`${down==null?'–':bitrate(down,'mbit')} ↓ · ${up==null?'–':bitrate(up,'mbit')} ↑`}
function meshClientNode(item){const {host,device,link,medium,connection,metric,confirmed}=item,q=link?quality(link):null,deviceClass=device?.['X_AVM-DE_DeviceClass'];return`<button class="mesh-node mesh-client ${confirmed?'confirmed':'derived'}" data-mesh-client-id="${esc(host.id)}" data-mesh-medium="${esc(medium)}"><span class="mesh-icon">${meshIcon(medium)}</span><span class="mesh-node-copy"><strong>${esc(clientName(host))}</strong><small>${esc(hostIp(host))} · ${esc([deviceClass&&deviceClass!=='Generic'?deviceClass:'',connection.ssid||connection.name||medium].filter(Boolean).join(' · '))}</small><small>${esc(meshRate(link,metric))}</small></span><span class="mesh-node-state ${q?.level||'unknown'}" title="${esc(q?.label||'Keine Qualitätsmessung')}"></span></button>`}
