const baseRenderAgentSection=renderAgentSection;
function captureViewPosition(){const roots=[$('#agent-panel'),$('#client-drawer')].filter(Boolean),scrolls=[];for(const root of roots){const elements=[root,...root.querySelectorAll('*')].filter(element=>element.scrollHeight>element.clientHeight+1||element.scrollWidth>element.clientWidth+1);scrolls.push(elements.map(element=>({top:element.scrollTop,left:element.scrollLeft})))}return{pageTop:document.scrollingElement?.scrollTop||window.scrollY,pageLeft:document.scrollingElement?.scrollLeft||window.scrollX,scrolls,details:roots.map(root=>[...root.querySelectorAll('details')].map(item=>item.open))}}
function restoreViewPosition(view){const roots=[$('#agent-panel'),$('#client-drawer')].filter(Boolean);roots.forEach((root,rootIndex)=>{const elements=[root,...root.querySelectorAll('*')].filter(element=>element.scrollHeight>element.clientHeight+1||element.scrollWidth>element.clientWidth+1);elements.forEach((element,index)=>{const saved=view.scrolls[rootIndex]?.[index];if(saved){element.scrollTop=saved.top;element.scrollLeft=saved.left}});[...root.querySelectorAll('details')].forEach((item,index)=>{const open=view.details[rootIndex]?.[index];if(open!==undefined)item.open=open})});if(document.scrollingElement){document.scrollingElement.scrollTop=view.pageTop;document.scrollingElement.scrollLeft=view.pageLeft}else window.scrollTo(view.pageLeft,view.pageTop)}
renderAgentSection=function(){const sameSection=state.lastRenderedSection===state.section,view=sameSection?captureViewPosition():null;if(!['wifi','network'].includes(state.section)&&state.selectedClient)closeClient();baseRenderAgentSection();if(state.selectedClient)renderClientDrawer();state.lastRenderedSection=state.section;if(view){restoreViewPosition(view);requestAnimationFrame(()=>restoreViewPosition(view))}};

// Live values are rendered into a detached snapshot and then morphed into the
// visible DOM. Existing elements, scroll containers, focus and event handlers
// stay intact. New or removed instances are inserted/removed by the same diff;
// the visible section is never rebuilt for a live update.
function liveNodeKey(node){if(node.nodeType!==Node.ELEMENT_NODE)return'';for(const name of ['id','data-param-path','data-client-id','data-mesh-client-id','data-functional-group','data-command','data-endpoint']){const value=node.getAttribute(name);if(value)return`${node.tagName}:${name}:${value}`}if(node.tagName==='TR'){const cells=[...node.cells].slice(0,2).map(cell=>cell.textContent.trim()).join('|');if(cells)return`TR:${cells}`}if(node.tagName==='ARTICLE'){const heading=node.querySelector('h2,h3,strong')?.textContent.trim();if(heading)return`ARTICLE:${node.className}:${heading}`}return''}
function compatibleLiveNode(current,fresh){return current&&fresh&&current.nodeType===fresh.nodeType&&(current.nodeType!==Node.ELEMENT_NODE||current.tagName===fresh.tagName)}
function morphLiveChildren(current,fresh){const desired=[...fresh.childNodes];for(let index=0;index<desired.length;index++){const freshChild=desired[index],key=liveNodeKey(freshChild);let currentChild=current.childNodes[index];if(key&&liveNodeKey(currentChild)!==key){const match=[...current.childNodes].slice(index+1).find(node=>liveNodeKey(node)===key);if(match){current.insertBefore(match,currentChild||null);currentChild=match}else{current.insertBefore(freshChild.cloneNode(true),currentChild||null);currentChild=current.childNodes[index]}}else if(!compatibleLiveNode(currentChild,freshChild)){current.insertBefore(freshChild.cloneNode(true),currentChild||null);currentChild=current.childNodes[index]}morphLiveDom(currentChild,freshChild)}while(current.childNodes.length>desired.length)current.lastChild.remove()}
function morphLiveDom(current,fresh){if(!compatibleLiveNode(current,fresh))return false;if(current.nodeType===Node.TEXT_NODE){if(current.nodeValue!==fresh.nodeValue)current.nodeValue=fresh.nodeValue;return true}if(current.nodeType!==Node.ELEMENT_NODE)return true;if(current.hasAttribute('data-live-preserve'))return true;const preserveValue=/^(INPUT|TEXTAREA|SELECT)$/.test(current.tagName),preserveOpen=current.tagName==='DETAILS';for(const attribute of [...current.attributes])if(!fresh.hasAttribute(attribute.name)&&!(preserveOpen&&attribute.name==='open'))current.removeAttribute(attribute.name);for(const attribute of [...fresh.attributes]){if(attribute.name==='hidden'||preserveOpen&&attribute.name==='open')continue;if(current.getAttribute(attribute.name)!==attribute.value)current.setAttribute(attribute.name,attribute.value)}if(!preserveValue)morphLiveChildren(current,fresh);return true}
function buildSectionSnapshot(){const current=$('#agent-panel');if(!current)return null;const snapshot=document.createElement('section');snapshot.id='agent-panel';snapshot.className=current.className;snapshot.hidden=true;current.id='agent-panel-current';current.parentNode.insertBefore(snapshot,current);const selected=state.selectedClient;state.selectedClient=null;try{baseRenderAgentSection()}finally{state.selectedClient=selected;current.id='agent-panel';snapshot.hidden=false;snapshot.remove()}return snapshot}
function patchClientDrawerLive(){const current=$('#client-drawer');if(!current||!state.selectedClient)return true;const snapshot=document.createElement('div');snapshot.id='client-drawer';snapshot.innerHTML='<div class="client-drawer-panel"></div>';snapshot.hidden=true;current.id='client-drawer-current';document.body.appendChild(snapshot);try{renderClientDrawer()}finally{current.id='client-drawer';snapshot.id='client-drawer-snapshot';snapshot.remove()}return morphLiveDom(current.querySelector('.client-drawer-panel'),snapshot.querySelector('.client-drawer-panel'))}
function bindDynamicLiveNodes(){if(['wifi','network'].includes(state.section))bindClientButtons();if(state.section==='network')bindMesh();if($('.functional-browser'))bindFunctionalPage();else if(state.section==='parameters')bindModelRows()}
function patchLiveSection(){
  const current=$('#agent-panel');if(!state.agent||!current)return;
  // These views already receive direct cell updates or are changed explicitly
  // by the user. Rebuilding their potentially very large tables would only add
  // work and could disturb an active form.
  if(['internet','parameters','jobs','events','actions','history'].includes(state.section)){patchClientDrawerLive();return}
  const view=captureViewPosition(),snapshot=buildSectionSnapshot();if(!snapshot)return;
  morphLiveDom(current,snapshot);bindDynamicLiveNodes();patchClientDrawerLive();restoreViewPosition(view)
}
scheduleLiveRender=function(){
  if(state.renderTimer||state.livePatchPending)return;
  state.renderTimer=setTimeout(()=>{
    state.renderTimer=null;state.livePatchPending=true;
    const endpoint=state.agent?.agent?.endpoint_id,section=state.section;
    const commit=()=>requestAnimationFrame(()=>{try{if(endpoint===state.agent?.agent?.endpoint_id&&section===state.section)patchLiveSection()}finally{state.livePatchPending=false}});
    if('requestIdleCallback'in window)requestIdleCallback(commit,{timeout:400});else commit()
  },120)
};

function deviceMemoryPercent(){const total=pnum('Device.DeviceInfo.MemoryStatus.Total'),free=pnum('Device.DeviceInfo.MemoryStatus.Free');return total>0&&free!=null?Math.max(0,Math.min(100,Math.round((total-free)/total*100))):null}
function deviceWanIp(){const direct=pvFirst(['Device.IP.Interface.1.IPv4Address.1.IPAddress','Device.IP.Interface.1.IPv6Address.1.IPAddress'],'');if(direct)return direct;const row=state.agent.parameters.find(item=>/^Device\.IP\.Interface\.(?!1000\.)\d+\.IPv[46]Address\.\d+\.IPAddress$/.test(item.path)&&item.value&&!['0.0.0.0','::'].includes(String(item.value)));return row?.value||'–'}
function deviceProvider(){return pvFirst(['Device.Cellular.Interface.1.X_AVM-DE_Provider','Device.Cellular.Interface.1.X_AVM_DE_Provider','Device.WAN.X_AVM-DE_Provider'],state.agent?.network?.provider||(state.agent?.network?.asn?state.agent.network.asn:accessType()))}
function resourceMeter(label,value,kind){const shown=value==null?'–':`${value}%`,level=value==null?'unknown':cpuLevel(value);return`<div class="resource-row"><div class="resource-label"><small>${label}</small><strong data-resource-value="${kind}">${shown}</strong></div><div class="cpu-meter ${level}" data-resource-meter="${kind}" role="meter" aria-label="${label}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${value??0}"><span style="width:${value??0}%"></span></div></div>`}

renderAgentShell=function(){
  const agent=state.agent.agent,online=Date.now()-new Date(agent.last_seen).getTime()<600000,cpu=Math.max(0,Math.min(100,Number(pv('Device.DeviceInfo.ProcessStatus.CPUUsage',0))||0)),memory=deviceMemoryPercent();
  $('#content').innerHTML=`<button class="secondary back" id="back">← USP-Agenten</button><section class="device-hero"><div><span class="eyebrow">${esc(accessType())} · ${esc(pv('Device.DeviceInfo.Manufacturer',agent.oui||'USP'))}</span><h2>${esc(pv('Device.DeviceInfo.ModelName',agent.product_class||'USP-Agent'))}</h2><p class="mono muted">${esc(agent.endpoint_id)}</p></div><div class="device-live">${status(online?'Online':'Offline',online?'good':'')}<span class="live-pill good">Live</span></div></section><div class="device-kpis"><div class="stat device-summary"><small>Uptime</small><strong class="compact" data-live-path="Device.DeviceInfo.UpTime">${uptime(pv('Device.DeviceInfo.UpTime',0))}</strong></div><div class="stat device-summary"><small>WAN-IP</small><strong class="compact mono" data-device-wan>${esc(deviceWanIp())}</strong></div><div class="stat device-summary"><small>Netz / Provider</small><strong class="compact" data-device-provider>${esc(deviceProvider())}</strong></div><div class="stat resource-stat">${resourceMeter('CPU',cpu,'cpu')}${resourceMeter('Speicher',memory,'memory')}</div></div><div class="device-workspace"><nav class="device-menu"><button data-section="overview">Übersicht</button><button data-section="system">System</button><button data-section="access">Anschluss</button><button data-section="internet">Internet & IP</button><button data-section="wifi">WLAN</button><button data-section="network">Heimnetz</button><button data-section="telephony">Telefonie & DECT</button><button data-section="management">USP & MQTT</button><span class="menu-separator">Analyse & Technik</span><button data-section="history">Messwerte</button><button data-section="parameters">Expertenansicht</button><button data-section="jobs">Aufträge</button><button data-section="events">Ereignisse</button><button data-section="actions">USP-Aktionen</button></nav><section id="agent-panel" class="device-panel"></section></div><dialog id="model-dialog" class="model-dialog"></dialog>`;
  $('#back').onclick=agents;$$('[data-section]').forEach(button=>button.onclick=()=>{clearTimeout(state.renderTimer);state.renderTimer=null;state.section=button.dataset.section;renderAgentSection();if(state.section==='telephony'&&!rowsAt('Device.Services.VoiceService.').length)refreshTelephony(true);if(state.section==='management'&&!state.agent.parameters.some(row=>(row.path.startsWith('Device.Services.')&&!row.path.startsWith('Device.Services.VoiceService'))||row.path.startsWith('Device.BulkData.')))refreshServices(true)});renderAgentSection()
};

updateShellLive=function(){
  if(!state.agent)return;const cpu=Math.max(0,Math.min(100,Number(pv('Device.DeviceInfo.ProcessStatus.CPUUsage',0))||0)),memory=deviceMemoryPercent();
  for(const [kind,value] of [['cpu',cpu],['memory',memory]]){const output=$(`[data-resource-value="${kind}"]`),meter=$(`[data-resource-meter="${kind}"]`);if(output)output.textContent=value==null?'–':`${value}%`;if(meter){meter.className=`cpu-meter ${value==null?'unknown':cpuLevel(value)}`;meter.setAttribute('aria-valuenow',String(value??0));const fill=meter.querySelector('span');if(fill)fill.style.width=`${value??0}%`}}
  const up=$('[data-live-path="Device.DeviceInfo.UpTime"]');if(up)up.textContent=uptime(pv('Device.DeviceInfo.UpTime',0));const wan=$('[data-device-wan]');if(wan)wan.textContent=deviceWanIp();const provider=$('[data-device-provider]');if(provider)provider.textContent=deviceProvider()
};
